// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_3: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.warped-terrain","name":"Warped Terrain","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","illusion","manipulate","visual","wizard"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":5,"text":"5-foot burst or more"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create illusory hazards that cover all surfaces in the area (typically the ground). Any creature moving through the illusion treats the squares as difficult terrain. A creature can attempt to disbelieve the effect as normal after using a action or otherwise spending actions interacting with the illusion. If it successfully disbelieves, it ignores the effect for the remaining duration. For each additional action you use casting the spell, the burst's radius increases by 5 feet, to a maximum of 10 extra feet for 3 actions.\n\nHeightened (4th) You can make the illusion appear in the air rather than on a surface, causing it to function as difficult terrain for flying creatures.","source":{"provider":"PAIZO","sourceId":"fXdADBwxmBsU9xPk","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wash-your-luck","name":"Wash Your Luck","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","fortune","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Some practitioners argue this spell literally washes your fortunes of all influences, malign or benign, while others claim it simply cleanses your mind of obsessions about luck and destiny. You adjust your garments, change the posture of your chair, fidget with a religious symbol, or make some other innocuous and personally significant action to wash away bad luck.\n\nOnce during the spell's duration, before rolling a check, you can cancel out a misfortune effect on that roll, as normal when a fortune and misfortune effect apply to the same roll. After canceling out the misfortune effect, the spell ends, and you are then temporarily immune to wash your luck for 10 minutes.","source":{"provider":"PAIZO","sourceId":"lmHmKGs1N3yNAvln","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.weaken-earth","name":"Weaken Earth","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature, unattended object, or hazard or structure made of stone or earth","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You weaken the bonds that hold earth and stone together. If your target has Hardness, you can affect one contiguous object, up to a 5-foot cube, or one creature, decreasing the Hardness by 5, to a minimum of 0. If the target lacks Hardness, it gains weakness 3 to physical damage. A target with a Fortitude modifier can attempt a Fortitude saving throw, negating the effect on a success.\n\nHeightened (+2) Hardness decreases by 5, the size of a contiguous object increases by one 5-foot cube, and the weakness increases by 3.","source":{"provider":"PAIZO","sourceId":"eyKkLp8V55ydA64J","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.weapon-surge","name":"Weapon Surge","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","sanctified"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 weapon you're wielding","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Holding your weapon aloft, you fill it with divine energy. On your next Strike with that weapon before the start of your next turn, you gain a +1 status bonus to the attack roll and the weapon deals an additional 1d6 spirit damage, and the Strike gains the sanctified trait. Weapon surge ends once you complete this Strike or the weapon leaves your possession.\n\nHeightened (5th) The attack deals 2d6 additional spirit damage.\n\nHeightened (9th) The attack deals 3d6 additional spirit damage.","source":{"provider":"PAIZO","sourceId":"W37iBXLsY2trJ1rS","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.weapon-trance","name":"Weapon Trance","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The serenity of violence fills your mind, giving you a heightened sense of knowing exactly where your weapons need to be. For the duration, your proficiency with martial weapons is equal to your proficiency with simple weapons.","source":{"provider":"PAIZO","sourceId":"RpGB961b8FjXbGHi","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.weave-wood","name":"Weave Wood","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 piece of unprocessed wood, reeds, or plant fiber of 1 Bulk or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a touch, you cause the target to break into fibrous strands that then weave themselves into a woven mundane object of the same Bulk or less, such as a basket, hat, shield, or mat. You can create up to 4 objects with one casting of this spell, providing their total Bulk doesn't exceed the Bulk of your target. The objects have Hardness 2 and 8 Hit Points.\n\nHeightened (+1) Increase the maximum Bulk that you can target by 1 and the maximum number of objects you can create by 2.","source":{"provider":"PAIZO","sourceId":"idcBYnj4DUHL0IJt","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.whispering-quiet","name":"Whispering Quiet","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","sonic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You suppress sound in an area, preventing anyone from giving away valuable secrets. This doesn't prevent those in the area from talking or Casting a Spell, but no creature more than 5 feet away can hear its voice without succeeding at a Perception check against your spell DC, which might interfere with auditory or linguistic effects as well as communication. Other sounds created in the area are muffled to a similar volume unless that sound is created by an effect with the sonic trait","source":{"provider":"PAIZO","sourceId":"1RxPW9I70Nd7wokz","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wildfire","name":"Wildfire","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"1","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A thin layer of ash and flame covers the ground in the area. The area becomes hazardous terrain. A creature that moves on the ground through the area takes 1 fire damage for every square of that area it moves into. A creature that ends its turn in the area must succeed at a Reflex save or take 1[persistent,fire] damage.\n\nEach time you sustain this spell, the radius of the burst increases by 5 feet.\n\nHeightened (+2) Increase the damage and persistent damage by 1.","source":{"provider":"PAIZO","sourceId":"jks2h5pMsm8pCi8e","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wilding-word","name":"Wilding Word","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","hex","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron's majesty—or their displeasure—comes in a growl from your throat, making other creatures reluctant to harm you. The target must attempt a Will save; if the creature is an animal, fungus, or plant, it takes a –1 circumstance penalty to its save.\n\nCritical Success The target is unaffected.\n\nSuccess When the target attempts an attack roll or skill check that would harm you, it takes a -2 status penalty to its roll.\n\nFailure As success, but the target also becomes Sickened 1 each time it damages you.\n\nCritical Failure As failure, but the sickened value is 2.","source":{"provider":"PAIZO","sourceId":"GdN5YQE47gd79k7X","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.winter-bolt","name":"Winter Bolt","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","cold","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You fling a hollow icicle filled with winter's wrath. Make a spell attack against the target's AC. The bolt deals 1d8 piercing damage and lodges in the target. At the end of the target's next turn, the bolt shatters, releasing a whirl of snow and ice that deals (@item.rank)d12[cold|options:area-damage] damage to the target and all adjacent creatures. The bolt can be removed with an Interact action, which causes it to melt harmlessly without detonating.\nCritical Success The initial bolt deals full damage and is especially well anchored, taking 2 Interact actions to remove. The bolt's explosion deals double damage.\n\nSuccess The bolt and its explosion deal full damage.\nHeightened (+1) The bolt's initial damage increases by 1d8 and the explosion damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"DeNz6eAUlE0IE9U3","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wish-market","name":"Wish Market","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You signal your willingness to make a deal, attracting ghostly merchants that eagerly and silently wave contracts for your consideration while demanding an esoteric price. When you Cast this Spell, you accept an offer from the merchants. You gain a +1 status bonus to Perception checks and your choice of Acrobatics, Athletics, Nature, Occultism, or Religion checks for the spell's duration, and you can either or [[/act seek]] as a free action. However, you also pay a random price; roll 1d4 on the table below. The first time each round you Sustain the spell, you can either Recall Knowledge or Seek as a free action or haggle with the merchant to suppress the price's penalty for 1 round.\n1d4\nEffect\n\n1\nYour Social Graces: For the spell's duration, you take a –2 status penalty to Diplomacy and Society checks.\n\n2\nYour Guile: For the spell's duration, you take a –2 status penalty to Deception and Stealth checks.\n\n3\nYour Manual Dexterity: For the spell's duration, you take a –2 status penalty to Crafting and Thievery checks.\n\n4\nYour Higher Reasoning: For the spell's duration, you take a –2 status penalty to Arcana and Medicine checks.\n\nHeightened (4th) The status bonus increases to +2.\n\nHeightened (7th) The status bonus increases to +3.","source":{"provider":"PAIZO","sourceId":"cYW9M2yE16dTTnCF","book":"Pathfinder Adventure Path: Hell's Destiny","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.withering-grasp","name":"Withering Grasp","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","concentrate","focus","manipulate","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature or object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d12","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d12","1":"1"}},"counteraction":false,"ritual":null,"description":"Your touch rots organic material and decays objects. Make a spell attack against the target's AC. Your touch deals 1d12 void damage plus 1d4 persistent void damage. If a creature uses an item to block withering grasp, such as with the Shield Block reaction, the item is automatically affected, but the creature doesn't take damage (even if there is damage left over after the shield's Hardness). Unlike normal void damage, the void damage from withering grasp damages objects, constructs, and the like by eroding away their substance.\nCritical Success Your touch deals double damage (both initial and persistent). If you target an object, lower its Hardness by 4 for 1 minute.\n\nSuccess Your touch deals full damage. If you target an object, lower its Hardness by 2 for 1 minute.\nHeightened (+1) The damage increases by 1d12 and the persistent damage increases by 1. If you target an object, lower its Hardness by an additional 1 point on both a success and a critical success.","source":{"provider":"PAIZO","sourceId":"7tp97g0UCJ9wOrd5","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.wooden-fists","name":"Wooden Fists","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","morph","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your arms and hands swell with new growth, transforming into tree trunks twice as big as their current size. Your fists deal 1d6 bludgeoning damage, lose the nonlethal trait, and have reach.\n\nHeightened (3rd) Your fists gain the magical trait and become a striking weapon, increasing the damage your fists deal to 2d6 bludgeoning.\n\nHeightened (7th) Your fists gain the magical trait and become a greater striking weapon, increasing the damage your fists deal to 3d6 bludgeoning. The duration is 10 minutes.\n\nHeightened (9th) Your fists gain the magical trait and become a major striking weapon, increasing the damage your fists deal to 4d6 bludgeoning. The duration is 1 hour.","source":{"provider":"PAIZO","sourceId":"IHjiWCouSacC5b3g","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.word-of-truth","name":"Word of Truth","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You speak a statement you believe to be true and that is free of any attempt to deceive through twisting words, omission, and so on. The statement must be 25 words or fewer. A symbol of your deity glows above your head and lasts for the spell's duration, and anyone who sees you and hears you speak knows that you believe what you say is true. This assurance of honesty grants you a +2 status bonus to Diplomacy checks as long as the symbol persists. You can Dismiss the spell, and if you say something that you don't believe is entirely true, the spell ends before you complete your statement.","source":{"provider":"PAIZO","sourceId":"aF7RiG7c8GzSQLYt","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.zenith-star","name":"Zenith Star","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","light","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call a tiny star to orbit a creature in a sparkling halo before shooting up into the heavens, where it marks the creature's rough location. The target must attempt a Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target is for 1 round.\n\nFailure The target is dazzled for 1 round. While the spell persists, as long as you can see the night sky and the target is visible from the same night sky, you can sense the approximate direction and distance to the creature by Sustaining the spell. This is enough to track the creature, but not pinpoint their exact square (for instance, to make an attack). You can set a number of zenith stars equal to your Wisdom modifier; if you exceed this number, your oldest zenith star is automatically Dismissed.\n\nCritical Failure As failure, but the target is for 1 round.\nHeightened (+1) The duration increases by 1 day.\n\nHeightened (4th) You ignore the condition against targets marked by zenith star.","source":{"provider":"PAIZO","sourceId":"Yrek2Yd4k3DPC2zV","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.acid-arrow","name":"Acid Arrow","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["acid","attack","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d8","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"You conjure an arrow of acid that keeps corroding the target after it hits. Make a spell attack against the target. On a hit, you deal 3d8 acid damage plus (floor(@item.rank/2))d6[persistent,acid] damage. On a critical hit, double the initial damage, but not the persistent damage.\nHeightened (+2) The initial damage increases by 2d8, and the persistent acid damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"f8hRqLJaxBVhF1u0","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.acid-grip","name":"Acid Grip","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["acid","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"YBeTuItHduzXElD5","formula":"2d8","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"YBeTuItHduzXElD5":"2d8"}},"counteraction":false,"ritual":null,"description":"An ephemeral, taloned hand grips the target, burning it with magical acid. The target takes 2d8 acid damage plus floor(@item.level/2)d6[persistent,acid] damage depending on its Reflex save. A creature taking persistent damage from this spell takes a –10-foot status penalty to its Speeds.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and no persistent damage, and the claw moves it up to 5 feet in a direction of your choice.\n\nFailure The creature takes full damage and persistent damage, and the claw moves it up to 10 feet in a direction of your choice.\n\nCritical Failure The creature takes double damage and full persistent damage, and the claw moves it up to 20 feet in a direction of your choice.\nHeightened (+2) The initial damage increases by 2d8, and the persistent acid damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"9h9YCncqah6VNsKf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.advanced-scurvy","name":"Advanced Scurvy","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","disease","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your touch afflicts the target with an advanced form of scurvy, a mariner's disease stemming from improper nutrition. The symptoms of scurvy include fatigue, joint pain, loose teeth, and internal hemorrhaging.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Enfeebled 1 for 1 minute.\n\nFailure The target is afflicted with advanced scurvy at stage 1.\n\nCritical Failure The target is afflicted with advanced scurvy at stage 2.\n\nAdvanced Scurvy (disease)\n\nLevel 4\n\nfor 1 day after eating fresh fruit, a creature gains a +2 circumstance bonus to their next saving throw against this affliction\n\nStage 1 enfeebled 1 and the damage dealt by persistent bleed effects is increased by 1 (1 day)\n\nStage 2 enfeebled 1, , and the damage dealt by persistent bleed effects is increased by 1d4 (2 days)\n\nStage 3 Enfeebled 2, fatigued, and the damage dealt by persistent bleed effects is increased by 1d6 (4 days)","source":{"provider":"PAIZO","sourceId":"XEhzFKNTSARsofav","book":"Pathfinder Adventure Path: Gatewalkers","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.albatross-curse","name":"Albatross Curse","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","misfortune"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute (see text)","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a spectral albatross, a guiding bird for sailors, to hover around the target. You and allies within 30 feet of the target gain a +1 circumstance bonus to attacks against the target. The target creature can spend an action to Strike the albatross, which automatically succeeds and kills it. The target must then attempt a Will save against your spell DC.\n\nCritical Success The target is unaffected.\n\nSuccess The guilt of slaughtering a bird of good fortune weighs on the target's mind. The target is Stupefied 1 for 1 round.\n\nFailure The albatross hangs around a cord from the target's neck (or closest equivalent) for 1 minute, cursing them for their transgression. During this time, the target must roll twice and take the worse result on their next Will save, after which the albatross disappears.\n\nCritical Failure As failure, but the duration is 1 hour.","source":{"provider":"PAIZO","sourceId":"93SjFTGJUTTmAt6j","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.allfood","name":"Allfood","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"target":"1 unattended non-magical object of 1 Bulk or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You transform one object into an edible substance that any living creature can chew, swallow, and safely digest. This allfood always has a bland taste and slightly gooey consistency, regardless of its original nature. One bulk of allfood provides enough sustenance to feed one Medium creature for a day.\n\nAfter 1 day, if no one has eaten the allfood, it reverts to its original form. Most Small creatures eat one-quarter as much as a Medium creature and most Tiny creatures eat one-sixteenth as much, while most Large creatures eat 10 times as much, Huge creatures need 100 times as much, and so on.\n\nHeightened (+1) Double the maximum bulk (to a maximum of 256 bulk at 10th level).","source":{"provider":"PAIZO","sourceId":"X3fWP6YCSzcdtg93","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animal-feature","name":"Animal Feature","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Without fully transforming your body, you gain one animalistic feature, which you select from the list below each time you Cast the Spell.\n\n- Cat Eyes You gain low-light vision.\n\n- Claws You gain a claw attack that deals 1d6 slashing damage and has the agile, finesse, and unarmed traits.\n\n- Jaws You gain a jaws attack that deals 1d8 piercing damage and has the unarmed trait.\n\nHeightened (4th) Add the following options to the list.\n\n- Fish Tail You gain a swim Speed equal to your land Speed.\n\n- Owl Eyes You gain darkvision.\n\n- Wings You gain a fly Speed equal to your land Speed.","source":{"provider":"PAIZO","sourceId":"vGEgI8e7AW6FQ3tP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animal-form","name":"Animal Form","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon primal energy to transform yourself into a Medium animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as lion or snow leopard for cat), but this has no effect on the form's Size or statistics. While in this form, you gain the animal trait. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which animal you choose:\n- AC = 16 + your level. Ignore your armor's check penalty and Speed reduction.\n- 5 temporary Hit Points.\n- Low-light vision and imprecise scent 30 feet.\n- One or more unarmed melee attacks specific to your battle form, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +9, and your damage bonus is +1. These attacks are Strength based (for the purpose of the condition, for example). If your unarmed attack bonus is higher, you can use it instead.\n- Athletics modifier of +9, unless your own modifier is higher.\nYou also gain specific abilities based on the type of animal you choose:\n- Ape\n- Speed 25 feet, climb Speed 20 feet;\n- Melee a fist, Damage 2d6 bludgeoning.\n\n- Bear\n- Speed 30 feet;\n- Melee a jaws, Damage 2d8 piercing;\n- Melee a claw (agile), Damage 1d8 slashing.\n\n- Bull\n- Speed 30 feet;\n- Melee a horn, Damage 2d8 piercing.\n\n- Canine\n- Speed 40 feet;\n- Melee a jaws, Damage 2d8 piercing.\n\n- Cat\n- Speed 40 feet;\n- Melee a jaws, Damage 2d6 piercing;\n- Melee a claw (agile), Damage 1d10 slashing.\n\n- Crab\n- Speed 25 feet, swim Speed 15 feet;\n- Melee a big claw, Damage 2d8 piercing;\n- Melee a little claw (agile), Damage 2d4 piercing.\n\n- Crocodile\n- Speed 25 feet, swim Speed 30 feet;\n- Melee a jaws, Damage 2d8 piercing;\n- Melee a tail (agile), Damage 1d8 bludgeoning.\n- can hold your breath for the duration of the transformation.\n\n- Deer\n- Speed 50 feet;\n- Melee a antler, Damage 2d6 piercing.\n\n- Frog\n- Speed 25 feet, swim Speed 25 feet;\n- Melee a jaws, Damage 2d6 bludgeoning;\n- Melee a tongue (reach 15 feet), Damage 2d4 bludgeoning.\n\n- Orca\n- swim Speed 35 feet;\n- Melee a jaws, Damage 2d8 piercing;\n- can hold your breath for the duration of the transformation.\n\n- Seal\n- Speed 20 feet, swim Speed 30 feet;\n- Melee a jaws (grapple), Damage 2d6 piercing;\n- can hold your breath for the duration of the transformation.\n\n- Shark\n- swim Speed 35 feet;\n- Melee a jaws, Damage 2d8 piercing;\n- breathe underwater but not in air.\n\n- Snake\n- Speed 20 feet, climb Speed 20 feet, swim Speed 20 feet;\n- Melee a fangs, Damage 2d4 piercing plus 1d6 poison.\n\nHeightened (3rd) You instead gain 10 temporary HP, AC = 17 + your level, attack modifier +14, damage bonus +5, and Athletics +14.\n\nHeightened (4th) Your battle form is Large and your attacks have 10-foot reach. You must have enough space to expand into or the spell is lost. You instead gain 15 temporary HP, AC = 18 + your level, attack modifier +16, damage bonus +9, and Athletics +16.\n\nHeightened (5th) Your battle form is Huge and your attacks have 15-foot reach. You must have enough space to expand into or the spell is lost. You instead gain 20 temporary HP, AC = 18 + your level, attack modifier +18, damage bonus +7 and double the number of damage dice, and Athletics +20.","source":{"provider":"PAIZO","sourceId":"wp09USMB3GIW1qbp","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animal-messenger","name":"Animal Messenger","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You offer food, and an ordinary Tiny animal within range approaches to eat it. You imprint the image, direction, and distance of an obvious place or landmark well known to you within the animal. You can also attach a small object or note up to light Bulk to it. The animal does its best to reach the destination; if it makes it there, it waits nearby and allows nonhostile creatures to approach and remove the attached object. The spell ends after the message is delivered or after 24 hours, whichever comes first.\n\nIf there are no Tiny wild animals in range, the spell is lost.","source":{"provider":"PAIZO","sourceId":"yhz9fF69uwRhnHix","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animate-object","name":"Animate Object","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils, see Creature Creation Rituals"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert)","secondaryChecks":"Crafting","secondaryCasters":1},"description":"You transform the target into an animated object with a level up to that allowed by the Creature Creation Rituals table and of a type corresponding to the object (so a broom would become an animated broom).\nCritical Success The target becomes an animated object of the appropriate type. If it's at least 4 levels lower than you, you can make it a minion. This gives it the minion trait, meaning it can use 2 actions when you command it, and commanding it is a single action that has the auditory and concentrate traits. You can have a maximum of four minions under your control. If it doesn't become a minion, you can give it one simple command. It pursues that goal single-mindedly, ignoring any of your subsequent commands.\n\nSuccess As critical success, except an animated object that doesn't become your minion stays in place and attacks anyone that attacks it or tries to steal or move it, rather than following your command.\n\nFailure You fail to create the animated object.\n\nCritical Failure You create the animated object, but it goes berserk and attempts to destroy you.\nCreatures Creation Rituals\nCreature LevelSpell Rank RequiredCost\n-1 or 0215 gp\n1260 gp\n23105 gp\n33180 gp\n44300 gp\n54480 gp\n65750 gp\n751,080 gp\n861,500 gp\n962,100 gp\n1073,000 gp\n1174,200 gp\n1286,000 gp\n1389,000 gp\n14913,500 gp\n15919,500 gp\n161030,000 gp\n171045,000 gp","source":{"provider":"PAIZO","sourceId":"sLzPzk7DJnfuORJ0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animated-assault","name":"Animated Assault","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You use your mind to manipulate unattended objects in the area, temporarily animating them to attack. The objects hover in the air, then hurl themselves at nearby creatures in a chaotic flurry of debris. This assault deals 2d10 bludgeoning damage (basic Reflex save) to each creature in the area. On subsequent rounds, the first time each round you Sustain this Spell, it deals (floor(@item.level/2))d10[bludgeoning] damage (basic Reflex save) to each creature in the area.\nHeightened (+2) The initial damage increases by 2d10 and the subsequent damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"WqPhJNzLa8vSjrH6","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.animus-mine","name":"Animus Mine","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"4d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"You implant a mental mine within your psyche that detonates against anyone attempting to magically manipulate your thoughts. You can Sustain the spell to suppress the effects of the mine for 1 round to allow someone to safely use a mental effect on you. You can Dismiss the spell. The first creature that uses a magical mental effect against you triggers the animus mine, causing the spell to end. The animus mine deals 4d8 mental damage to the triggering creature, which must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Stunned 1.\n\nCritical Failure The creature takes double damage and is stunned 1. You're unaffected by the triggering mental effect.\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"fWU7Qjp1JiX9g6eg","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.army-of-shadows","name":"Army of Shadows","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["darkness"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"}},"targeting":{"range":{"kind":"TEXT","text":"1,000 feet"},"area":{"shape":"BURST","feet":200}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert) or Warfare Lore (expert)","secondaryCasters":0},"description":"You conjure a squadron of shadows to surge forth and plunge your enemies into darkness. All non-magical light sources in the area are extinguished and can't be lit again during the duration. Any dim light from sources outside the area can't penetrate the area, and sources of bright light from outside the area shed only dim light into the area. The shadows also attempt to counteract any magical light in the area, with a counteract rank of 2 and a counteract modifier of [[/r 1d20+13 #Counteract]]{+13}. If a new magical light effect enters the area during the duration, the shadows immediately attempt to counteract it.\nCritical Success The shadows are particularly powerful. Their counteract rank increases by 1, and they gain a +2 circumstance bonus to their counteract check.\n\nSuccess The shadows are of normal power.\n\nFailure The ritual has no effect.\n\nCritical Failure The shadows instead cling to you and obscure your vision, rendering you for 24 hours.\nHeightened (4th) The shadows have a counteract rank of 4 and a counteract modifier of [[/r 1d20+18 #Counteract]]{+18}.\n\nHeightened (6th) The shadows have a counteract rank of 6 and a counteract modifier of [[/r 1d20+24 #Counteract]]{+24}.\n\nHeightened (8th) The shadows have a counteract rank of 8 and a counteract modifier of [[/r 1d20+29 #Counteract]]{+29}.","source":{"provider":"PAIZO","sourceId":"WfImUYSXyW3YdyY9","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ash-cloud","name":"Ash Cloud","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["air","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d4","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You summon a tumultuous cloud of ash and smoke. The cloud is difficult terrain for flying creatures, and creatures in the cloud can't detect anything using their sense of smell. Creatures that start their turn within the cloud take 2d4 fire damage as their lungs fill with the hot, acrid smoke, with a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage and is for 1 round.\n\nCritical Failure The target takes double damage and is for 1 round.\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"23cv1p49NFd0Onng","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.augury","name":"Augury","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain a vague glimpse of the future. During the casting of this spell, ask about the results of a particular course of action. The spell can predict results up to 30 minutes into the future and reveal the GM's best guess among the following outcomes: good, bad, mixed (the results will be a mix of good and bad), and nothing (there won't be particularly good or bad results).\n\nThe GM rolls a secret flat. On a failure, the result is always \"nothing.\" This makes it impossible to tell whether a \"nothing\" result is accurate. If anyone asks about the same topic as the first casting of augury during an additional casting, the GM uses the secret roll result from the first casting. If circumstances change, though, it's possible to get a different result.","source":{"provider":"PAIZO","sourceId":"41TZEjhO6D1nWw2X","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.avenging-wildwood","name":"Avenging Wildwood","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A Medium tree sprouts in an unoccupied square within range, its branches capable of striking out at your foes. This animated tree uses your spell attack modifier for its attack rolls and your spell DC for its AC. Its saving throw modifiers are equal to your spell DC – 10, and it has 20 Hit Points. Other creatures can't occupy its space, but allies can pass through its space. When you Cast the Spell and each time you Sustain it, you can have the tree make a branches Strike against a creature within 15 feet of it, dealing 2d8 bludgeoning, piercing, or slashing damage. You choose the damage type each time.\n\nIf the tree is in soil and survives to the end of the spell's duration, it remains as an ordinary, non-magical tree and continues to grow and thrive. The GM might determine that the tree disappears immediately in certain inhospitable situations.\nHeightened (+2) The animated tree has 10 additional Hit Points, and its branches Strike deals 1d8 additional damage.","source":{"provider":"PAIZO","sourceId":"T7N0LrYOLk3SwrFW","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.banishing-touch","name":"Banishing Touch","kind":"SPELL","rank":2,"rarity":"RARE","traits":["attack","concentrate","manipulate","mythic"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SPELL_ATTACK"},"damage":[{"id":"wn2U6jvbMUgcTC2a","formula":"1d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your touch projects a surge of magic that launches your target safely away. Make a melee spell attack at mythic proficiency against your target's AC. If you hit, you deal 1d6 bludgeoning damage, and you launch the target into the air and away from you; the target takes falling damage as normal. The number of actions you spend while Casting the Spell determines the damage dealt by your touch and how far the target is launched.\n\n1 The target is launched 10 feet into the air and knocked back 10 feet.\n\n2 Your touch deals 2d6 bludgeoning damage instead. The target is launched 20 feet into the air and pushed back 10 feet.\n\n3 Your touch deals 2d6 bludgeoning damage instead. The target is launched 30 feet into the air and pushed back 20 feet.\nHeightened (4th) The initial damage increases by 1d6, and all distances increase by 10 feet for the 1-action version or 20 feet for the 2- and 3-action versions.\n\nHeightened (6th) The initial damage increases by 2d6, and all distances increase by 20 feet for the 1-action version or 60 feet for the 2- and 3-action versions.\n\nHeightened (8th) The initial damage increases by 3d6, and all distances increase by 30 feet for the 1-action version or 100 feet for the 2- and 3-action versions.","source":{"provider":"PAIZO","sourceId":"nKR6Xt5cPGDumX66","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.bee-mans-summons","name":"Bee-Man's Summons","kind":"SPELL","rank":2,"rarity":"RARE","traits":["auditory","concentrate","linguistic","mental"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":500}},"duration":{"text":"until the next time you make your daily preparations or until discharged","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You recreate the Bee-Man's infamous ability to sense when someone utters their name. During the spell's duration, you mentally sense whenever someone (referred to as a speaker) speaks your full name while within the spell's area. You gain a vague sense of the speaker's identity, such as \"a local farmer\" or \"a halfling in distress,\" unless the speaker is someone you have met and interacted with before, in which case you recognize the speaker specifically. As a reaction within 1 minute of the speaker's utterance, you can send the speaker a telepathic prompt, asking if they intend to summon you. If they respond affirmatively, the spell's remaining duration decreases to sustained (up to 10 minutes), during which time you know the direction to where the speaker named you and how far away they are.\n\nHeightened (4th) The emanation's radius increases to 1,000 feet.\n\nHeightened (7th) The emanation's radius increases to 1 mile, and instead of locating the speaker, you can instead converse with the speaker for 5 minutes. This otherwise works as sending.\n\nHeightened (9th) As 7th, except the emanation's radius increases to 5 miles, and the duration of the conversation is 10 minutes.","source":{"provider":"PAIZO","sourceId":"BcqJqxIKYE0aoDiS","book":"Pathfinder #201: Pactbreaker","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.befitting-attire","name":"Befitting Attire","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"5 willing creatures","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cloak the targets in an illusion, shaping their clothing and worn items into ones suitable for a particular occasion. You visualize the occasion, and the spell creates illusory attire customized to each target. For instance, if you visualized a noble ball, armor would appear to be fine clothing. This doesn't change identifying details of the targets' appearances other than their clothes.\n\nAny creature that touches the attire, uses the Seek action to examine it, or otherwise interacts with it can attempt to disbelieve your illusion.\n\nHeightened (4th) You can target up to 20 creatures.\n\nHeightened (5th) You can target up to 100 creatures.","source":{"provider":"PAIZO","sourceId":"q5qmNn144ZJGxnvJ","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.binding-muzzle","name":"Binding Muzzle","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A shimmering muzzle of pure magical force clamps the target's mouth shut. The target can attempt a Fortitude save to resist the muzzle. For targets with more than one mouth, the caster must target a single mouth.\n\nCritical Success The target is unaffected.\n\nSuccess For 1 round, the target can't use jaws Strikes, Breath Weapons, or any other attack that originates from the mouth, nor can they imbibe anything, including potions, mutagens, and elixirs.\n\nFailure As success, but the effect lasts 1 minute, and they must succeed at a flat to Cast a Spell with verbal components.\n\nCritical Failure As success, but the effect lasts 1 minute and the target can't speak.\n\nHeightened (5th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"lrFKkzgz80B5vTBb","book":"Pathfinder #195: Heavy is the Crown","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blast-of-the-bellows","name":"Blast of the Bellows","kind":"SPELL","rank":2,"rarity":"RARE","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a churning eddy of warm air that makes it difficult to fly within the area. This area is difficult terrain for flying creatures. Each time a flying creature enters the area or ends its turn there, it must attempt an Acrobatics check to .\n\nSuccess The creature is unaffected.\n\nFailure The creature descends 30 feet.\n\nCritical Failure The creature descends 60 feet.\n\nHeightened (4th) The duration increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"bZ8BibvvYOKAbYjn","book":"Pathfinder #195: Heavy is the Crown","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blazing-armory","name":"Blazing Armory","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"As long as you have magic, you're never unarmed. You materialize a flaming simulacrum of any common simple or martial weapon into the target's grasp. The target must have a free hand to hold the weapon, or else the weapon falls to the ground in the target's space. The blazing weapon functions as a +1 striking weapon, and its damage type changes to fire. The damage type can't be changed using the versatile trait, modular trait, or similar methods.\n\nA thrown weapon rematerializes in the target's hand after the Strike is complete. If you choose a ranged weapon that uses ammunition, the wielder must still reload the weapon using the normal number of actions, though this generates ammunition automatically; this functions as normal ammunition, and the blazing weapon can't use other types of ammunition.\n\nAny creature other than you or the target that attempts to touch, make a Strike with, or the weapon takes 1d6[fire] damage each time.\n\nHeightened (4th) You can target up to 5 willing creatures and can choose a different weapon for each target. The weapons function as +1 striking flaming weapons.\n\nHeightened (6th) As 4th, but the weapons function as +2 greater striking flaming weapons.\n\nHeightened (8th) As 4th, but the weapons function as +3 greater striking greater flaming weapons.\n\nHeightened (10th) As 4th, but the weapons function as +3 major striking greater flaming weapons.","source":{"provider":"PAIZO","sourceId":"ywHwnXihTnXbm9Xq","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blazing-blade","name":"Blazing Blade","kind":"SPELL","rank":2,"rarity":"RARE","traits":["attack","concentrate","fire","holy","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":true}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A scimitar-shaped beam of fiery light springs from your free hand. While the spell lasts, you can use a single action, which has the attack and concentrate traits, to burn your foes with the blazing blade. When you do, make a spell attack roll. On a success, the blazing blade deals 1d6 fire damage plus 1d6 spirit damage plus your spellcasting ability modifier. On a critical success, it deals double the usual damage.\n\nHeightened (4th) The blade's fire damage increases to 2d6. On a critical success, the target takes (ternary(gte(@item.level,8),3,ternary(gte(@item.level,6),2,1)))d6[persistent,spirit] damage.\n\nHeightened (6th) The blade's fire damage increases to 3d6. On a critical success, the target takes 2d6 persistent spirit damage.\n\nHeightened (8th) The blade's fire damage increases to 4d6. On a critical success, the target takes 3d6 persistent spirit damage.","source":{"provider":"PAIZO","sourceId":"NacrNSvfODxpZena","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.blazing-bolt","name":"Blazing Bolt","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 or more creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fire a ray of heat and flame. Make a spell attack roll against a single creature. On a hit, the target takes 2d6 fire damage, and on a critical hit, the target takes double damage.\n\nFor each additional action you use when Casting the Spell, you can fire an additional ray at a different target, to a maximum of three rays targeting three different targets for 3 actions. These attacks each increase your multiple attack penalty, but you don't increase your multiple attack penalty until after you make all the spell attack rolls for blazing bolt. If you spend 2 or more actions Casting the Spell, the damage increases to 4d6 fire damage on a hit, and it still deals double damage on a critical hit.\n\nHeightened (+1) The damage to each target increases by 1d6 for the 1-action version, or by 2d6 for the 2-action and 3-action versions.","source":{"provider":"PAIZO","sourceId":"ZxHC7V7HtjUsB8zH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blistering-invective","name":"Blistering Invective","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["auditory","concentrate","emotion","fear","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"A heap of insults and invectives spew from your mouth-words so devastating your foes burn from the intensity of your diatribe. Your words deal 2d6 persistent fire damage, and the target must attempt a Will save. If the target doesn't understand the language or you're not speaking a language, it gains a +4 circumstance bonus to its save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half the persistent fire damage.\n\nFailure The target becomes Frightened 1 and takes the full persistent fire damage.\n\nCritical Failure The target becomes Frightened 2 and takes double the persistent fire damage.\n\nHeightened (+2) You can target two additional creatures, and the persistent damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"hoR6w8BqX2F35Tdx","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blood-duplicate","name":"Blood Duplicate","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 non-magical object of 1 Bulk or less","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This spell deals you 1 piercing damage as you shape a magical duplicate of the target from your blood; you can't cast this spell if you don't have blood. This spell can't duplicate an item made of precious materials, or materials with a rarity of uncommon or higher. If you're ever more than 5 feet from the duplicate, the spell's duration immediately ends. The Perception DC to recognize the duplicate as false using any sense except touch is equal to 10 + your spellcasting ability modifier + your Crafting proficiency bonus. The item feels wet and obviously fake to the touch. When the spell ends, the item collapses into a puddle of blood that quickly evaporates.","source":{"provider":"PAIZO","sourceId":"crf7EL1JtBYwvAEg","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blood-vendetta","name":"Blood Vendetta","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["curse"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"REACTION"},"requirements":"You can bleed"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"The triggering creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Requirements You can bleed.\n\nTrigger A creature deals piercing, slashing, or persistent bleed damage to you.\n\nYou curse the target, punishing it for having the audacity to spill your blood. The target takes 2d6 persistent bleed damage and must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half the persistent bleed damage.\n\nFailure The target takes the full persistent bleed damage. Until the bleeding stops, the target has weakness 1 to piercing and slashing damage.\n\nCritical Failure As failure, but the target takes double the persistent bleed damage.\n\nHeightened (+2) The persistent bleed damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"TaaMEYdZXQXF0Sks","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blur","name":"Blur","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's form appears blurry. It becomes . As the nature of this effect still leaves the target's location obvious, the target can't use this concealment to Hide or Sneak.","source":{"provider":"PAIZO","sourceId":"3JG1t3T4mWn6vTke","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bonding-meal","name":"Bonding Meal","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"10 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Cooking Lore, Crafting, Performance, or Survival (trained)","secondaryCasters":0},"description":"Many grow up and spend their lives eating with others, and doing so binds them—to their families, communities, and cultures. Food can form long-lasting bonds, and with a bit of extra work, those bonds can be shared.\n\nYou prepare a meal for a small gathering of up to 10 close friends, enough people to comfortably eat together at one table or in one circle. As you collect and prepare the food, you call upon spirits of home and memory. As they work through you and guide you, you perfectly recreate a dish that emotionally connects you to a place of your past: perhaps your mother's cooking when you were a child, or the way you and your comrades-in-arms cooked rations together when you fought in the war. When you're done, you share the meal and tell your new friends the story that comes with it. As they eat and drink, any participants of 4th level or lower sink into a snapshot of your past and can borrow insights from it for future use.\nCritical Success Your friends are vividly taken through your memories as you relive them, and they hold onto the experience even after the fugue ends. For the next week, they have a +4 circumstance bonus to Deception and Diplomacy checks to convince anyone from the community where the meal originated from that they are from that area or were present for events you described. Even after the raw magic infusing the memories fade, the memories don't, and your friends will be able to make the dish just as well as you can. Chances are, they like it just as much as you did.\n\nSuccess As critical success, except your friends get a +2 circumstance bonus to Deception and Diplomacy checks instead. They also can't make the meal themselves but probably look forward to tasting it the way you make it if you ever offer to cook it again.\n\nFailure Your friends see the vision as planned, but the magic doesn't quite take. As success, but no one receives any bonus. The real treasure will have to be the friends you fed along the way.\n\nCritical Failure Your friends see the vision as planned, and the magic takes hold—but it goes wrong, like a bad case of indigestion. The memories are scattered around the rest of their psyches, and it takes a week to settle down properly. They confuse parts of your past for theirs, and they take a –2 circumstance bonus to Deception and Diplomacy checks for the next week against anyone from your old community, as they confidently apply the wrong expectations from their lives across the one you were trying to introduce them to.\nHeightened (4th) Participants up to 8th level can gain the benefits, and the cost is 40 gp.\n\nHeightened (6th) Participants up to 12th level can gain the benefits, and the cost is 150 gp.\n\nHeightened (8th) Participants up to 16th level can gain the benefits, and the cost is 480 gp.\n\nHeightened (10th) Participants of any level can gain the benefits, and the cost is 2000 gp.","source":{"provider":"PAIZO","sourceId":"aYn7Xgrz4vIMNeIc","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bone-spray","name":"Bone Spray","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d10","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10","1":"1"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You fire a torrent of jagged bone shards from your hands, dealing 2d10 piercing damage and 1 persistent bleed damage to all creatures in the area.\n\nHeightened (+1) The piercing damage increases by 1d10 and the persistent bleed damage increases by 1.","source":{"provider":"PAIZO","sourceId":"S708JF3E0kuhuRzG","book":"Pathfinder #176: Lost Mammoth Valley","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.boneshaker","name":"Boneshaker","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 creature with a skeleton","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"ohmjnqzezb9q8i8x","formula":"3d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"ohmjnqzezb9q8i8x":"3d8"}},"counteraction":false,"ritual":null,"description":"You reach out a hand and seize a creature's skeleton from afar, harming their body and potentially wrenching them by the bones to move them against their will. The number of actions you spend when Casting this Spell determines the spell's effects. Regardless of the number of actions spent to Cast this Spell, the target must attempt a Fortitude save.\n\n2 (somatic, verbal) You clench your fist, painfully compressing the target's bones and dealing 3d8 bludgeoning damage.\n\n3 (material, somatic, verbal) As the 2-action version, plus you pull the target's body by their bones, moving them around like an awkward marionette. This movement follows the rules for forced movement.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage. If you cast the 3-action version, you can move the target up to 5 feet; it can choose to fall to avoid moving.\n\nFailure The target takes full damage and is Enfeebled 1. If you cast the 3-action version, you can move the target up to 15 feet; it can fall prone to avoid moving.\n\nCritical Failure The target takes double damage and is Enfeebled 2. If you cast the 3-action version, you can move the target up to 25 feet, then knock the target prone; if you attempt to move the target to a hazardous location, such as into a pool of acid or off a cliff, it can fall prone to avoid moving.\n\nHeightened (+2) The damage increases by 3d8.","source":{"provider":"PAIZO","sourceId":"zdNUbHqqZzjA07oM","book":"Pathfinder #176: Lost Mammoth Valley","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bralani-referendum","name":"Bralani Referendum","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["air","concentrate","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"ZpsiSWQOvyrSkfMK","formula":"2d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"ZpsiSWQOvyrSkfMK":"2d6"}},"counteraction":false,"ritual":null,"description":"You enforce fair play with punishing zephyrs. When you Cast this Spell, choose one condition from among , , , or . When a creature in the area inflicts the chosen condition, they take 2d6 slashing damage with a basic Fortitude save. A creature can't take this damage more than once per round. You can Dismiss the spell.\n\nHeightened (+2) Choose one more condition. The slashing damage when a creature inflicts any of the chosen conditions increases by 2d6.","source":{"provider":"PAIZO","sourceId":"SspI4ijjR7N7r4Cc","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.brand-the-impenitent","name":"Brand the Impenitent","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You brand the target with an ethereal copy of your deity's religious symbol. This brand can't be hidden, but it is visible only to followers of your faith, who see it as clearly as a lit torch. Followers of your faith ignore the target's condition, if any, and the target gains a -1 status penalty to AC against attacks by followers of your faith. If the target is a follower of your deity in good standing, the spell fails.\n\nCritical Success The target is unaffected.\n\nSuccess The spell lasts for 1 round.\n\nFailure The spell lasts for 1 minute.\n\nCritical Failure The spell has an unlimited duration.","source":{"provider":"PAIZO","sourceId":"Y8cSjhU33oUqccxJ","book":"Pathfinder Lost Omens Gods & Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.breath-of-drought","name":"Breath of Drought","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","fire","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You fill the area with an oppressive, arid swelter that overwhelms creatures with heat exhaustion. Objects are unaffected. Each creature in the area when the spell is cast or that ends its turn in the area afterward must attempt a Fortitude save. Water creatures and plant creatures use the outcome one degree of success worse than the result of their saving throw. Creatures whose bodies contain no significant moisture (such as fire elementals) are immune to breath of drought.\n\nSuccess The creature is unaffected.\n\nFailure The creature is Sickened 1.\n\nCritical Failure The creature is Sickened 2.\n\nHeightened (4th) Once per round when you Sustain the Spell, you can move the center of the burst to a new location within range.\n\nHeightened (7th) As the 4th-rank version, except the range is 120 feet and the area is a 20-foot burst.","source":{"provider":"PAIZO","sourceId":"Wt94cw03L77sbud7","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.brine-dragon-bile","name":"Brine Dragon Bile","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["acid","attack","concentrate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the creature that took damage","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"lFwT0JKtqmiZhm2D","formula":"2d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"lFwT0JKtqmiZhm2D":"2d6"}},"counteraction":false,"ritual":null,"description":"Trigger A creature within range takes damage from a slashing or piercing attack, or one that inflicts persistent bleed damage.\n\nYou spit a glob of caustic saltwater that stings the wounds of the creature. Make a ranged spell attack against the triggering creature's AC. On a hit, salt scours its open wound, dealing 2d6 persistent acid damage.\n\nHeightened (+2) The persistent damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"eidmNlfl2DUVIclc","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.burrow-ward","name":"Burrow Ward","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You solidify the earth around you, hindering burrowing creatures. Creatures that can't burrow through stone can't burrow through the area. Such creatures already underground within the area must succeed at a Fortitude save or be ejected from the area toward the surface. Those who succeed are forced out of the area but can remain underground. Creatures that can burrow through stone treat the area as difficult terrain.\n\nHeightened (5th) You create a .","source":{"provider":"PAIZO","sourceId":"bgX4Zfhavahu8lyN","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.buzzing-servants","name":"Buzzing Servants","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one unoccupied 5-foot square","area":{"shape":"SQUARE","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a swarm of bees from the city of Axis that rapidly constructs geometric shapes from wax. The bees appear in an unoccupied square, building a structure of hexagons, squares, and decagons that fill the space. The wax shape has a Hardness of 10 and 40 Hit Points but also decays over 24 hours.\n\nWhen you Sustain the spell, you can choose another unoccupied square in range that the bees move to and fill with wax shapes. Any amount of area or splash damage to the square they're present in kills the bees, ending further construction.","source":{"provider":"PAIZO","sourceId":"U7415tttUO8JLvpf","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.calm","name":"Calm","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You forcibly calm creatures in the area, soothing them into a nonviolent state; each creature must attempt a Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess Calming urges impose a -1 status penalty to the creature's attack rolls.\n\nFailure Any emotion effects that would affect the creature are suppressed and the creature can't use hostile actions. If the target is subject to hostility from any other creature, it ceases to be affected by calm.\n\nCritical Failure As failure, but hostility doesn't end the effect.","source":{"provider":"PAIZO","sourceId":"b515AZlB0sridKSq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.canopy-crawler","name":"Canopy Crawler","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"yourself or your animal companion","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target grows a prehensile tail, or gains prehensile qualities in their existing tail, to help them climb with ease. For the duration of the spell, they gain a climb Speed equal to their highest Speed. The target can Climb with a hand occupied (or two hands occupied if they have the feat).\n\nHeightened (5th) The spell's duration increases to 1 hour, and you can target both yourself and your animal companion with a single casting.","source":{"provider":"PAIZO","sourceId":"3JQPqtE7fkscP3f6","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.carrion-mire","name":"Carrion Mire","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The ground opens into a seemingly endless mass of corpse limbs, grasping at all creatures within the area to drag them down. Creatures in the area when the spell is cast or beginning their turn in the area must succeed at a Reflex save or fall . When a creature in the spell's area would be healed by a vitality effect, the carrion mire attempts to counteract that effect, preventing that healing but not otherwise preventing the effect if it's counteracted.","source":{"provider":"PAIZO","sourceId":"24JgGrYx7ixgP4kn","book":"Pathfinder Wake the Dead #4","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cauterize-wounds","name":"Cauterize Wounds","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","healing","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 5 willing creatures","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You seal bleeding wounds with fire. Any target that has persistent bleed damage can choose to take 1[fire|immutable:true] damage. If it does, it can attempt to recover from its persistent bleed damage, with the lower DC for particularly effective assistance. During the spell's duration, you can use a single action, which has the concentrate trait, to repeat this effect for one target of the spell.","source":{"provider":"PAIZO","sourceId":"sBSalosrt7C4IXas","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.charitable-urge","name":"Charitable Urge","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You speak on the virtue of charity, compelling the target to give away its possessions. The target must attempt a Will save. If the target has no items on its person, the spell fails.\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1 as it wrestles with the urge.\n\nFailure On its next turn, before it does anything else, the target must present the nearest creature with an item in its possession; the target chooses which item to give, and if the only item it has is one that it's currently using to defend itself, such as a weapon during a combat encounter, it can choose to be stunned for 1 round instead of giving up the item. This might require the target to Interact to retrieve an item or move to reach the nearest creature, and passing the item off requires an Interact action as normal.\n\nCritical Failure As failure, except the duration is 4 rounds, and the target must repeat the effects of a failure on each of its turns. At the end of each of its turns, the target can attempt a new Will save to reduce the remaining duration by 1 round, ending the effects entirely on a critical success.","source":{"provider":"PAIZO","sourceId":"UirEIHILQgip87qv","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clad-in-metal","name":"Clad In Metal","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 metal object of 5 Bulk or less that's unattended or attended by a willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You briefly swap the outer surface of the metal in an object with a suitable amount of a common precious metal from the Plane of Metal. You can instead choose an uncommon or rare metal if you have access to it or the GM has given you access to it.\n\nThe object functions as an item of that metal, provided the item would be 2nd level or lower. For example, you could make a dagger into a cold iron or silver dagger (2nd-level items) but couldn't make full plate into cold iron armor or silver armor (5th-level items). This imparts any special properties of the precious metal—a weapon clad in cold iron activates weaknesses to cold iron, for example—and suppresses any special properties of the original metal of which the item was made.\n\nThe spell neither changes the structural integrity of the item nor damages it. The object can pass a cursory inspection, but the magical effect is obvious to anyone who studies the item closely, so it doesn't alter the Price of the item if you attempt to sell it.\n\nHeightened (+1) The maximum level of the precious metal increases by 2.","source":{"provider":"PAIZO","sourceId":"7dBxguCNWCoPYxIi","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.claws-of-the-otter","name":"Claws of the Otter","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Webbing grows between your fingers and your nails extend into vicious claws. For the spell's duration, you gain a +1 status bonus to Athletics checks to Swim and you gain a claws unarmed attack. They're an agile, finesse, unarmed attack that deals 1d4 slashing damage and an additional 1d6 cold damage.\n\nHeightened (+3) The additional cold damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"yNTfght6fu9WYKmx","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clawsong","name":"Clawsong","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature with an unarmed claw Strike","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You sing a fierce prayer, low and growling, and awaken the ancient spirit of a Terwa beast to guide and strengthen the target's unarmed blows.\n\nThe target's claw attack gains the versatile (piercing) trait, and deals 1d6 slashing damage. If the target's claw attack already deals 1d6 slashing damage, it deals 1d8 instead.\n\nIf its claw attack already had the versatile (piercing) trait, it gains the deadly 1d8 trait.\nHeightened (4th) The spell can affect up to 6 willing creatures with unarmed claw Strikes.","source":{"provider":"PAIZO","sourceId":"7OFKYR1VY6EXDuiR","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cleanse-affliction","name":"Cleanse Affliction","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Gentle restorative magic pushes back the effects of toxins and more complex maladies. Choose an affliction on the target, such as a curse, disease, or poison. If it has advanced past stage one, reduce the stage by one. This reduction can be applied only once to a given case of an affliction, with the case ending when it's completely cured. Although the reduction can't occur again, heightened versions of this spell attempt to counteract with each casting.\n\nHeightened (3rd) Attempt to counteract the affliction if it is a disease or poison.\n\nHeightened (4th) Attempt to counteract the affliction if it is a curse, disease, or poison.","source":{"provider":"PAIZO","sourceId":"SUKaxVZW2TlM8lu0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cleanse-air","name":"Cleanse Air","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You purify the air in the area, making it clean and breathable. The spell immediately removes inhaled poisons, pollution, and similar contaminants from the air. For the remaining duration, the spell prevents any further contamination from altering air in the area, including keeping toxic air bordering the area from coming inside. (This doesn't prevent contaminants from coming in after the spell ends.) This spell doesn't create air, so casting it underwater wouldn't create breathable air, nor would it affect any toxins within air suspended in the water\n\nHeightened (3rd) The area increases to 60 feet.\n\nHeightened (4th) The area increases to 120 feet.\n\nHeightened (6th) The area increases to 500 feet.\n\nHeightened (9th) The area increases to 1 mile.","source":{"provider":"PAIZO","sourceId":"ElpqHitq4FqwLURV","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clear-mind","name":"Clear Mind","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","healing","manipulate","mental"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You drive mental contamination from the target's mind. Attempt to counteract an effect of your choice imposing one of these conditions on the target: , , and . If you failed to counteract the effect but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect's duration doesn't elapse while it's suppressed. This spell can't counteract or suppress conditions that are part of curses, diseases, or a natural state of the target.\nHeightened (4th) Add , , and to the list of conditions.\n\nHeightened (6th) As 4th rank, plus add .\n\nHeightened (8th) As 4th rank, plus add doomed and .","source":{"provider":"PAIZO","sourceId":"EfFMLVbmkBWmzoLF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.coiling-dance","name":"Coiling Dance","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","holy","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You perform a dance that seeks to pass on the knowledge and wisdom of a naga. Your allies in the area are filled with sacred energy, making their spells and attacks holy. Creatures or effects that would be unholy don't gain this benefit\n\nWhen you cast or Sustain this spell, you can choose an ally in the area that's , , or . They can immediately use a reaction to ; they can use your Occultism or Religion modifier for the check instead of their unarmed attack, Acrobatics, or Athletics modifier if that would be better.","source":{"provider":"PAIZO","sourceId":"RcZbmSZf2bFYQtTj","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.confetti-cloud","name":"Confetti Cloud","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":90},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a dense storm of swirling confetti. All creatures within the area of the confetti become , and all creatures outside the storm become concealed to creatures within it. Additionally, creatures in the area of the confetti continually hear the raucous sounds of a party or festival and take a –2 circumstance penalty on Perception checks to hear. The number of actions you spend when Casting this Spell determines its area. You can Dismiss the spell.\n\n1 (somatic) The spell's area is a .\n\n2 (somatic, verbal) The spell's area is a .\n\n3 (material, somatic, verbal) The spell's area is a .","source":{"provider":"PAIZO","sourceId":"CI7F5qdwp6YngyFt","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.consecrate","name":"Consecrate","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["consecration"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"3 days"},"cost":"rare incense and offerings worth a total value of 20 gp × the spell rank"},"targeting":{"range":{"kind":"DISTANCE","feet":40},"area":{"shape":"BURST","feet":40}},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion","secondaryChecks":"Crafting, Performance","secondaryCasters":2},"description":"Area 40-foot-radius burst around an immobile altar, shrine, or fixture of your deity\n\nSecondary Casters 2, must be worshippers of your religion\nYou consecrate a site to your deity, chanting praises and creating a sacred space. While within the area, worshippers of your deity gain a +1 status bonus to attack rolls, skill checks, saving throws, and Perception checks, and creatures anathema to your deity (such as undead for Pharasma or Sarenrae) take a -1 status penalty to those rolls. If your deity's divine sanctification allows you to choose holy or unholy, you can choose to make the consecrated site holy or unholy as well. If the deity's sanctification must be holy or unholy, you must make the site match that sanctification. Strikes made by worshippers of your deity within the area gain the site's sanctification trait, if any.\nCritical Success The consecration succeeds, and it either lasts for 10 years instead of 1 or covers an area with twice the radius. Occasionally, with your deity's favor, this might produce an even more amazing effect, such as a permanently consecrated area or the effect covering an entire cathedral.\n\nSuccess The consecration succeeds.\n\nFailure The consecration fails.\n\nCritical Failure The consecration fails spectacularly and angers your deity, who sends a sign of displeasure. For at least 1 year, further attempts to consecrate the site fail.\nHeightened (7th) The consecrated area also gains the effects of the planar seal spell, but the effect doesn't attempt to counteract teleportation by worshippers of your deity. The cost increases to 200 gp × the spell rank.","source":{"provider":"PAIZO","sourceId":"Dbd5W6G8U2vzWolN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.corpse-communion","name":"Corpse Communion","kind":"RITUAL","rank":2,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare spices and seasonings worth a total value of 50 gp × the spell rank"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (master), Occultism (expert), Religion (expert)","secondaryCasters":0},"description":"The dead hold more secrets than the living ever shall. The lore possessed by the dead will only increase as time marches on. To be alive is to define your knowledge as being limited, but with the corpse communion ritual, you can, if only for a short time and through a narrow aperture, tap into the greater lore of the dead and make use of it for your own designs.\n\nWhen you perform this grisly ritual, you consume a portion of a dead body, taking the decayed flesh and old bones into your system while also taking into your mind the memories etched into those mortal remains. The corpse from which you harvest your necromantic meal cannot have been dead for longer than 1 month, and it need not even be entirely intact, but enough should be present to form what would be regarded as a satisfying meal. If, in life, the corpse was the same ancestry as your own, then you gain a +2 circumstance bonus on the primary check to cast corpse communion. Note that when you perform corpse communion, the remains you consume are largely a symbolic bridge between this material world and the world of the dead. The ritual allows you to tap into the vast amount of knowledge and secrets held by the dead as a whole, not simply knowledge that may have once been held by the creature you feed upon.\n\nWhen you perform this ritual, select a single Intelligence-, Wisdom-, or Charisma-based skill whose secrets you wish to delve into, but in which you possess no greater proficiency in than trained.\n\nThe ritual itself does not protect you from potential infection from eating decayed flesh, and at the GM's discretion, performing this ritual could expose you to a disease, curse, or other affliction.\n\nIf you perform corpse communion again while already under its effects, the effects of any previous success or critical success are replaced by the results of the new ritual casting.\n\nCritical Success You learn a significant piece of lore, a forgotten secret, or some other tantalizing nugget of knowledge that is of immediate use to you, connected to the skill you chose. The GM will provide you with some piece of information they know will aid you in your personal goals. In addition, you become trained in the use of the selected skill and gain a +1 status bonus on checks made with that skill.\n\nSuccess You become expert in the use of the selected skill.\n\nFailure You fail to learn anything from the communion.\n\nCritical Failure A malevolent spirit, be it a supernatural presence sensing an opportunity or the soul of the corpse you're feeding upon, lashes out at you as you feed, drawing from you your memories and secrets and taking them away into the realm of the dead forever. You not only become Stupefied 3, but you no longer know the corpse communion ritual. You can attempt to learn it again, but the DC to learn this ritual increases by 5.\n\nHeightened (4th) The remains can be up to 10 years old-dry bones in sufficient enough quantity to gnaw upon will suffice. You can choose a skill you are trained or untrained in, and when you are successful at this ritual, you become master at that skill. The ritual duration extends to 1 week.\n\nHeightened (8th) The remains can be up to 100 years old-dry bones in sufficient enough quantity to gnaw upon will suffice. You can choose a skill you are trained or untrained in, and when you are successful at this ritual, you become master at that skill. The ritual duration extends to 1 month.\n\nHeightened (10th) The limit on how old the corpse must be is removed entirely-as long as enough remains, even if it's just a single skull, you can perform the ritual. You can choose a skill you are trained or untrained in, and when you are successful at this ritual, you become legendary at that skill. The ritual duration is permanent until you cast corpse communion again.","source":{"provider":"PAIZO","sourceId":"WRmh1aKEo0dI0NJs","book":"Pathfinder #184: The Ghouls Hunger","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-food","name":"Create Food","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create enough food to feed six Medium creatures for a day. This food is bland and unappealing, but it is nourishing. After 1 day, if no one has eaten the food, it decays and becomes inedible. Most Small creatures eat one-quarter as much as a Medium creature (one-sixteenth as much for most Tiny creatures), and most Large creatures eat 10 times as much (100 times as much for Huge creatures and so on).\n\nHeightened (4th) You can feed 12 Medium creatures.\n\nHeightened (6th) You can feed 50 Medium creatures.\n\nHeightened (8th) You can feed 200 Medium creatures.","source":{"provider":"PAIZO","sourceId":"Mt6ZzkVX8Q4xigFq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-undead","name":"Create Undead","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["unholy"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"black onyx, see Creature Creation Rituals table"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 dead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert), Occultism (expert), or Religion (expert)","secondaryChecks":"Religion","secondaryCasters":1},"description":"You transform the target into an undead creature with a level up to that allowed in the Creature Creation Rituals table. There are many versions of this ritual, each specific to a particular type of undead (one ritual for all zombies, one for skeletons, one for ghouls, and so on), and the rituals that create rare undead are also rare. Some forms of undead, such as liches, form using their own unique methods and can't be created with a version of create undead.\nCritical Success The target becomes an undead creature of the appropriate type. If it's at least 4 levels lower than you, you can make it a minion. This gives it the minion trait, meaning it can use 2 actions when you command it, and commanding it is a single action that has the auditory and concentrate traits. You can have a maximum of four minions under your control. If it's intelligent and doesn't become a minion, the undead is helpful to you for awakening it, though it's still a horrid and evil creature. If it's unintelligent and doesn't become a minion, you can give it one simple command. It pursues that goal single-mindedly, ignoring any of your subsequent commands.\n\nSuccess As critical success, except an intelligent undead that doesn't become your minion is only friendly to you, and an unintelligent undead that doesn't become your minion leaves you alone unless you attack it. It marauds the local area rather than following your command.\n\nFailure You fail to create the undead.\n\nCritical Failure You create the undead, but its soul, tortured by your foul necromancy, is full of nothing but hatred for you. It attempts to destroy you.\nCreatures Creation Rituals\nCreature LevelSpell Rank RequiredCost\n-1 or 0215 gp\n1260 gp\n23105 gp\n33180 gp\n44300 gp\n54480 gp\n65750 gp\n751,080 gp\n861,500 gp\n962,100 gp\n1073,000 gp\n1174,200 gp\n1286,000 gp\n1389,000 gp\n14913,500 gp\n15919,500 gp\n161030,000 gp\n171045,000 gp","source":{"provider":"PAIZO","sourceId":"c3b6LdLlQDPngNIb","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cutting-insult","name":"Cutting Insult","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","emotion","fear","linguistic","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"Pf4kebYTSq4tLAM1","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"oPR8OTVWWJD0xr3H","formula":"1","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Pf4kebYTSq4tLAM1":"4d6","oPR8OTVWWJD0xr3H":"1"}},"counteraction":false,"ritual":null,"description":"You utter an insult so offensive that it cuts your target to the quick. Your target takes 4d6[mental] damage and 1 persistent bleed damage and must attempt a Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half mental damage but no persistent bleed damage, and it becomes Frightened 1.\n\nFailure The creature takes full mental damage and full persistent bleed damage, and it becomes Frightened 2.\n\nCritical Failure The creature takes double mental damage and double persistent bleed damage, and becomes Frightened 3.\n\nHeightened (+2) The mental damage increases by 4d6, and the bleed damage increases by 1.","source":{"provider":"PAIZO","sourceId":"1hLxZznnA2kvXlIt","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.dancing-shield","name":"Dancing Shield","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 touched shield (unattended or in your possession) and 1 willing creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You levitate the touched shield and send it to orbit around a creature. When you Cast the Spell and Sustain it, the shield uses the Raise a Shield action to protect the target creature.\n\nHeightened (4th) If you have the reaction, you can use your reaction to have the target shield use Shield Block when the target creature would take damage from a physical attack, in addition to the usual trigger. In this case, Shield Block protects the target creature, rather than you. Since the shield is using Shield Block and not you, additional effects or abilities that normally apply when you Shield Block don't apply.","source":{"provider":"PAIZO","sourceId":"8Hw3P6eurX1MYm7L","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.darkness","name":"Darkness","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","darkness","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a shroud of darkness that prevents light from penetrating or emanating within the area. Light does not enter the area and any non-magical light sources, such as a torch or lantern, do not emanate any light while inside the area, even if their light radius would extend beyond the darkness. This also suppresses magical light of your darkness spell's rank or lower. Light can't pass through, so creatures in the area can't see outside. From outside, it appears as a globe of pure darkness.\n\nHeightened (4th) Even creatures with darkvision (but not greater darkvision) can barely see through the darkness. They treat targets seen through the darkness as .","source":{"provider":"PAIZO","sourceId":"4GE2ZdODgIQtg51c","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.darkvision","name":"Darkvision","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You grant yourself supernatural sight in areas of darkness. You gain Darkvision.\n\nHeightened (3rd) The spell's range is touch and it targets 1 willing creature.\n\nHeightened (5th) The spell's range is touch and it targets 1 willing creature. The duration is until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"pZTqGY1MLRjgKasV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deafness","name":"Deafness","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target loses hearing; it must attempt a Fortitude save. The target is then temporarily immune for 1 minute.\n\nCritical Success The target is unaffected.\n\nSuccess The target is for 1 round.\n\nFailure The target is Deafened for 10 minutes.\n\nCritical Failure The target is Deafened permanently.","source":{"provider":"PAIZO","sourceId":"fZPCv2VHuM2yPbC8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.death-knell","name":"Death Knell","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","death","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature that has 0 HP","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You snuff the life out of a creature on the brink of death. The target must attempt a Will save. If this kills it, you gain 10 temporary HP and a +1 status bonus to attack and damage rolls for 10 minutes.\n\nCritical Success The target is unaffected.\n\nSuccess The target's value increases by 1.\n\nFailure The target dies.","source":{"provider":"PAIZO","sourceId":"dLdRqT6UxTKlsPgp","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dismantle","name":"Dismantle","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 non-magical object in your possession of 1 Bulk or less","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You touch an object, and it immediately disassembles itself into its component pieces. The spell fails if the target lacks component pieces (such as a statue carved from one block of stone), and using it on a dangerous object like a snare or trap typically triggers it. The object gains the condition, and the component pieces become small enough to be under normal clothing and armor. You can the spell.\n\nWhen the spell ends, the object reassembles itself into its original form, appearing in your hand or hands if you have them free, or on the ground in front of you otherwise. Once reassembled, the object loses the Broken condition and its Hit Points return to the value the object had when you Cast the Spell.\nHeightened (4th) The spell lasts for 10 minutes.\n\nHeightened (6th) The spell lasts until your next daily preparations.","source":{"provider":"PAIZO","sourceId":"jW2asKFchuoxniSH","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dispel-magic","name":"Dispel Magic","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 spell effect or unattended magic item","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You unravel the magic behind a spell or effect. Attempt a counteract check against the target. If you successfully counteract a magic item, the item becomes a mundane item of its type for 10 minutes. This doesn't change the item's non-magical properties. If the target is an artifact or similar item, you automatically fail.","source":{"provider":"PAIZO","sourceId":"9HpwDN4MYQJnW0LG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-zone","name":"Elemental Zone","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Select an elemental trait: air, earth, fire, metal, water, or wood. Elemental zone gains the trait you chose. You imbue the area with the raw energy of that element, creating a zone that emits and amplifies magic of that type. The temperature might suddenly rise or fall, a storm cloud might form, and so on. Spells with the chosen elemental trait cast against creatures in the zone get a +2 status bonus to one damage type the spell deals based on the chosen trait: bludgeoning or electricity for air, bludgeoning for earth, fire for fire, electricity or slashing damage for metal, bludgeoning or cold for water, and bludgeoning or vitality damage for wood. The caster chooses one type to add the bonus to if the spell deals more than one eligible type. This bonus is halved if the spell didn't use a spell slot (such as a cantrip, focus spell, or innate spell).\n\nThe zone has no effect on the spell if the spell doesn't deal any damage of an eligible type.\n\nHeightened (+2) The status bonus increases by 1.","source":{"provider":"PAIZO","sourceId":"kMffb6SvhCBMMI4k","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.embed-message","name":"Embed Message","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object or willing creature","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You specify a trigger and a message up to 25 words long. When the specified trigger occurs within 30 feet of the target, illusory text of your message circles the target accompanied by a disembodied voice. You can choose a language you know for the text and speech, and can choose what the voice sounds like. Once the message is completed, the spell ends.\n\nHeightened (4th) You can add a simple sensory component to emphasize the message, such as an odor, visual effect, or physical sensation. This addition is obviously illusory and part of the message, lasting only while the message is being read.\n\nHeightened (6th) As 4th rank, but you can choose how many times the spell repeats the message before it ends; there is no limit to the number of repetitions.","source":{"provider":"PAIZO","sourceId":"eIQ86FOXK34HiNLs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.empathic-link","name":"Empathic Link","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You forge a bond between yourself and the target, enabling you to feel each other's emotions. You and the target can communicate empathetically, sharing emotions, at a distance of up to 1 mile.\n\nHeightened (4th) You can target up to 4 willing creatures, and the duration increases to 8 hours.","source":{"provider":"PAIZO","sourceId":"obVA6duK5fGbfFUY","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.empty-pack","name":"Empty Pack","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 container of 2 Bulk or less","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You render every item inside the container you touch , although the container itself remains visible. The items within are to all creatures, though a creature can attempt to find an item by reaching into the bag, making an item hidden to them instead if they succeed. Additionally, the spell doesn't prevent the items from making protrusions in the bag, adding weight, making noise when jostling around, and so on. However, the spell prevents anything within the container from falling out if it's upended. Any object removed from the container becomes visible and remains visible even if returned to the container.\nHeightened (4th) The duration is until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"CQWTyDxiVSW4uRn7","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enhance-victuals","name":"Enhance Victuals","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"up to 1 gallon of non-magical water or up to 5 pounds of food","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You transform the target into delicious fare, changing water into wine or another fine beverage or enhancing the food's taste and ingredients to make it a gourmet treat.\n\nPrior to the transformation, the spell attempts to counteract any poisons in the food or water. The food turns back to normal if not consumed before the duration expires, though any poisons that were counteracted are still gone.\n\nHeightened (+1) The number of gallons of water you can target increases by 1, or the number of pounds of food you can target increases by 5.","source":{"provider":"PAIZO","sourceId":"rdTEF1hfAWbN58NE","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enlarge","name":"Enlarge","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Bolstered by magical power, the target grows to size Large. Its equipment grows with it but returns to natural size if removed. The creature is Clumsy 1. Its reach increases by 5 feet (or by 10 feet if it started out Tiny), and it gains a +2 status bonus to damage rolls on melee Strikes. This spell has no effect on a Large or larger creature.\n\nHeightened (4th) The creature instead grows to size Huge. The status bonus to melee damage is +4 and the creature's reach increases by 10 feet (or 15 feet if the creature started out Tiny). The spell has no effect on a Huge or larger creature.\n\nHeightened (6th) Choose either the 2nd-rank or 4th-rank version of this spell and apply its effects to up to 10 willing creatures.","source":{"provider":"PAIZO","sourceId":"wzctak6BxOW8xvFV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enlarge-companion","name":"Enlarge Companion","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","polymorph","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your animal companion","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your animal companion grows much larger, towering over its foes in battle. Your animal companion becomes Large, gaining the effects of a 2nd-rank spell.\n\nHeightened (4th) Your animal companion instead becomes Huge, gaining the benefits of a 4th-rank enlarge spell","source":{"provider":"PAIZO","sourceId":"8rj45fKzCFcB0fxs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entangling-flora","name":"Entangling Flora","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20,"text":"all squares in a 20-foot-radius burst that contain plants"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Plants and fungi burst out or quickly grow, entangling creatures. All surfaces in the area are difficult terrain. Each round that a creature starts its turn in the area, it must attempt a Reflex save. On a failure, it takes a –10-foot circumstance penalty to its Speeds until it leaves the area, and on a critical failure, it's also for 1 round. Creatures can attempt to to remove these effects.","source":{"provider":"PAIZO","sourceId":"J6vNvrUT3b1hx2iA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.environmental-endurance","name":"Environmental Endurance","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shield the target against dangerous temperatures. Choose severe cold or heat. The target is protected from the temperature you chose (but not extreme cold or heat).\n\nHeightened (3rd) The target is protected from severe cold and severe heat.\n\nHeightened (5th) The target is protected from severe cold, severe heat, extreme cold, and extreme heat.","source":{"provider":"PAIZO","sourceId":"5esP2GVzvxWsMgaX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.erase-trail","name":"Erase Trail","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":40}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{},"areaFeet":20},"counteraction":false,"ritual":null,"description":"You drastically reduce all signs of one specific creature's passage from the area, including footprints, handprints, dirt, and minor changes caused to the surrounding environment, like the bending of grass. The DC of checks to or and discover such signs within the area gains a +4 status bonus or is equal to your spell DC, whichever is higher. This spell doesn't repair objects the creature damaged, return slain creatures to life, or remove objects or garbage left behind. It also doesn't prevent others from noticing that the creature's trail ends or begins abruptly outside the area. Finally, this spell doesn't hide the creature from sight or prevent them from leaving new signs of their presence after this spell is cast.\n\nHeightened (+2) The range increases by 100 feet, the area increases by 20 feet, and you can remove all signs of 1 additional creature's passage from the area.","source":{"provider":"PAIZO","sourceId":"Tw9e2rPaNdxcM1Rp","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.everlight","name":"Everlight","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"a gemstone worth 6 gp or more","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The gemstone you touch glows, spreading bright light with a color of your choice in a 20-foot radius (and dim light for the next 20 feet). The spell ends immediately if the gemstone is broken.","source":{"provider":"PAIZO","sourceId":"ynm8JIU3sc3qUMpa","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.expeditious-excavation","name":"Expeditious Excavation","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"CUBE","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area (continued) cube of dirt 5 feet across or smaller\nYou remove loose dirt, dust, gravel, sand, and the like (though not solid stone) up to the size of a 5-foot cube. Any Medium or smaller creature standing atop the earth when the spell is cast must attempt a Reflex save or acrobatics check.\n\nSuccess The creature is unaffected and can choose to either descend the pit without damage or move to the nearest available space of its choice.\n\nFailure The creature falls in the nearest available space of its choice or falls into the pit if it prefers.\n\nCritical Failure The creature falls into the pit excavated by the spell and lands prone, taking falling damage as normal.\nHeightened (+2) The spell can excavate an additional 5-foot cube of earth. If you excavate all four 5-foot cubes beneath a Large creature, it must attempt a Reflex save or Acrobatics check, as above.","source":{"provider":"PAIZO","sourceId":"aXoh6OQAL57lgh0a","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.exploding-earth","name":"Exploding Earth","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"Geqm5hIIStYgyT4R","formula":"4d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"pIJeJKjOcf4CSjCe","formula":"1d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Geqm5hIIStYgyT4R":"2d6","pIJeJKjOcf4CSjCe":"1d6"}},"counteraction":false,"ritual":null,"description":"You throw a hard-packed ball of earth and stone at a creature, and the projectile explodes upon impact. Attempt a spell attack against the target's AC. If you hit, you deal 4d6 bludgeoning damage plus 1d6 bludgeoning splash damage. On a critical hit, double the initial damage, but not the splash damage, and the target you hit must succeed at a Fortitude saving throw or fall .\n\nHeightened (+2) The damage increases by 2d6, and the splash damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"v89KwyaBd6g5rWVS","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.extract-poison","name":"Extract Poison","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 poison on or in an object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With the lightest touch, you can siphon the poison from an object and save it for your own later use, making an assassin's blade or politician's wine less deadly while you become all the more so. Attempt a counteract check against one poison you're aware of on or in an object you touch. If you successfully counteract the poison, you negate the object's toxicity and transfer the poison into a weapon you are holding, coating the weapon with a simple but powerful poison. On your next successful attack with that weapon before the end of your next turn, you add 1d6 poison damage per level of the poison you counteracted. On a critically failed attack roll, you lose the extracted poison from your weapon as normal.","source":{"provider":"PAIZO","sourceId":"CLThxp8Qf43IQ3Sb","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.faerie-fire","name":"Faerie Fire","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"All creatures in the area when you cast the spell are limned in colorful, heatless fire of a color of your choice for the duration. Visible creatures can't be while affected by faerie fire. If the creatures are , they are Concealed while affected by faerie fire, rather than being .","source":{"provider":"PAIZO","sourceId":"HRb2doyaLtaoCfi3","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.false-vitality","name":"False Vitality","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You augment your flesh with the energies typically used to manipulate the undead. You gain 10 temporary Hit Points.\n\nHeightened (+1) The temporary Hit Points increase by 3.","source":{"provider":"PAIZO","sourceId":"8ViwItUgwT4lOvvb","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.falsify-heat","name":"Falsify Heat","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","illusion","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing creature or object","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You veil the signs of the fires of vitality, altering the target's apparent body temperature. This illusion applies to all senses, and a creature that touches the target can attempt to disbelieve the illusion. You can Dismiss the spell. Choose an illusory body temperature when you cast the spell.\n\n- Moderate The target's body temperature appears the same as the surrounding environment, giving the target a +2 circumstance bonus to Deception checks to Impersonate an undead, a cold-blooded creature, or an inanimate object (such as a corpse). The target is also to heatvision and other abilities that sense heat similarly.\n\n- Warm The target appears to emit substantial body heat, gaining a +2 circumstance bonus to Deception checks to Impersonate a warm-blooded creature.\n\nHeightened (4th) You can target up to 10 creatures, and you can choose a different body temperature for each of them.","source":{"provider":"PAIZO","sourceId":"udZEKwUryIsobjBG","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.far-flung-fetch","name":"Far-Flung Fetch","kind":"SPELL","rank":2,"rarity":"RARE","traits":["manipulate","subtle","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 unattended object of light Bulk or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can pilfer an object even if it's outside the reach of your fingers. You teleport the target into one of your open hands. If you don't have a hand free, it falls to the ground at your feet.\nHeightened (3rd) The range increases to 120 feet.\n\nHeightened (5th) The range increases to 120 feet, and you can target an unattended object with a Bulk of 1 or less.\n\nHeightened (7th) As 5th rank, and when you Cast the Spell you can spend 3 actions instead of 1 to increase the range to planetary. If you do, you don't need line of sight to the target, but you must be extremely familiar with the target.","source":{"provider":"PAIZO","sourceId":"O6BIfXsbiisKfLTe","book":"Pathfinder NPC Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fear-the-sun","name":"Fear the Sun","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cause the creature's vision to become particularly sensitive. The creature must attempt a Fortitude save. The creature is then temporarily immune for 1 minute.\nCritical Success The creature is unaffected.\n\nSuccess The creature is for 1 round.\n\nFailure The creature is dazzled for 1 minute.\n\nCritical Failure The creature gains for 1 minute. If the creature is already exposed to bright light, it immediately becomes until the end of its next turn, as it isn't acclimated to its newly acquired light blindness.\nHeightened (6th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"vctIUOOgSmxAF0KG","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.feast-of-ashes","name":"Feast of Ashes","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"1d4","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You curse the target with a hunger no food can sate. You can Dismiss the spell. The target must attempt a Fortitude save.\nCritical Success The creature is unaffected and is temporarily immune for 1 hour.\n\nSuccess The creature is for 1 round.\n\nFailure The creature is immediately afflicted by hunger as if it hadn't eaten food in days. It becomes fatigued and takes 1d4 damage each day that can't be healed until it sates its hunger. No amount of eating can sate the creature's hunger during the spell's duration.\n\nCritical Failure As failure, but the creature takes 2d4 damage each day from unbearable hunger.\nHeightened (+1) The hunger becomes more intolerable, increasing the damage each day by 1d4, or by 2d4 on a critical failure.","source":{"provider":"PAIZO","sourceId":"siU9xRlqWXeKT0mH","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.feral-shades","name":"Feral Shades","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4","1":"1d4"}},"counteraction":false,"ritual":null,"description":"A wave of gray mist formed of void energy spills out from your outstretched hand, briefly taking the shape of a pack of predatory animals that set viciously on your foes. You deal 2d4 slashing damage and 2d4 void damage to creatures in the area. The shades set upon the vulnerable with greater ferocity: prone creatures or those taking persistent bleed damage take a -2 status penalty to the save.\n\nHeightened (+1) The slashing damage and the void damage each increase by 1d4.","source":{"provider":"PAIZO","sourceId":"Ru9v8U9IRk3LtWx8","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.final-sacrifice","name":"Final Sacrifice","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature with the minion trait that you summoned or permanently control","area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You channel disruptive energies through the bond between you and your minion, causing it to violently explode. The target is immediately slain, and the explosion deals 6d6 fire damage to creatures within 20 feet of it with a basic Reflex save. If the target has the cold or water trait, the spell deals cold damage and has the cold trait instead of the fire trait. Attempting to cast this spell targeting a creature that you temporarily seized control of, such as an undead commanded by bind undead, automatically fails and breaks the controlling effect.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"x0rWq0wS06dns4G2","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fireproof","name":"Fireproof","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object up to 10 Bulk","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prevent the target item from conducting heat or catching fire for the spell's duration. The item gains fire resistance 10. In addition, effects with the fire trait that target the item must first succeed at a counteract check against your spell DC.\n\nHeightened (4th) The duration is 24 hours.\n\nHeightened (6th) The duration is unlimited.","source":{"provider":"PAIZO","sourceId":"QLTgY1AqFvX82vq2","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flame-wisp","name":"Flame Wisp","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"Three faintly glowing wisps of fire float around your head. Each time you hit a creature with a Strike, one of the wisps goes hurtling towards that creature, dealing 1d4 fire damage. If you Cast a Spell with the fire trait while you have fewer than three wisps, a new wisp appears.\n\nHeightened (+2) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"3q9tBMWsWQKlXPPJ","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.floating-flame","name":"Floating Flame","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"SQUARE","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You create a fire that burns without fuel and moves to your commands. The flame deals 3d6 fire damage to each creature in the square in which it appears, with a basic Reflex save. When you Sustain this spell, you can levitate the flame up to 10 feet. It then deals damage to each creature whose space it shared at any point during its flight. This uses the same damage and save, and you roll the damage once each time you Sustain. A given creature can take damage from floating flame only once per round.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"2ZdHjnpEQJuqOYSG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.frog-tongue","name":"Frog Tongue","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"j7ydKn5ZNVgLaHIY","formula":"2d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"j7ydKn5ZNVgLaHIY":"2d8"}},"counteraction":false,"ritual":null,"description":"Your tongue extends unnaturally, flicking out toward a creature within range and dealing 2d8 bludgeoning damage (basic Reflex save). On a failure, the creature is also stuck to the end of the tongue. It is and can't move beyond the reach of your tongue. A creature can sever the tongue with a Strike that deals at least 10 slashing damage or attempt to against your spell DC. The AC of the tongue is equal to your spell DC. Severing the tongue in this way deals no damage to you but ends the spell. While a creature is stuck to the end of your tongue, actions you take with the auditory trait take a –2 circumstance penalty. If you move so that the affected creature is outside of the tongue's reach, the spell ends.\n\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"cnRltZAjU9aCklqz","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fungal-hyphae","name":"Fungal Hyphae","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fungus","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Thin hyphae grow from your feet and plunge into the earth, creating a symbiotic fungal network that attaches to plants within 30 feet and connects you to their root systems. You gain an imprecise tremorsense, allowing you to sense anything directly touching plants within that distance. If you move, the hyphae snap, and the spell ends.\nHeightened (4th) You can control plants in the area to a small degree, allowing you to make Strikes with tree branches, exposed roots, or similarly solid plants. To do so, you use a Strike action, but you can Strike any creature you can detect with your tremorsense. These are spell attacks that deal 3d8[bludgeoning] damage. Unusual plants, such as thorny vines, might deal a different type of damage at the GM's discretion. You can't make any other attacks through these plants, or take any other actions through them, other than these Strikes.\n\nHeightened (6th) As 4th rank, but you can use other simple manipulate actions through the plants, including having a branch pick an object up or open a door, though more complex actions, such as picking a lock or disabling a trap, remain impossible.","source":{"provider":"PAIZO","sourceId":"oNUyCqbpGWHifS02","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fungal-infestation","name":"Fungal Infestation","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fungus","manipulate","poison"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Toxic spores swarm over creatures in the area, causing them to erupt in grotesque fungal growths. These noxious growths deal 2d6 persistent poison damage, and each creature must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The target takes half the persistent poison damage.\n\nFailure The target takes the full persistent poison damage. While it's taking this persistent poison damage, it has weakness 1 to fire and weakness 1 to slashing.\n\nCritical Failure As failure, but double the persistent poison damage. While it's taking this persistent poison damage, it has weakness 2 to fire and weakness 2 to slashing.\n\nHeightened (+2) The persistent damage increases by 2d6, and the weakness increases by 1, or by 2 on a critical failure.","source":{"provider":"PAIZO","sourceId":"3VxVbZqIRvpKkg3O","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.gecko-grip","name":"Gecko Grip","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Tiny clinging hairs sprout across the creature's hands and feet, offering purchase on nearly any surface. The target gains a climb Speed equal to its Speed.\n\nHeightened (5th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"5KobTMrZeZxuXMgl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gentle-breeze","name":"Gentle Breeze","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["air","concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":40}},"duration":{"text":"10 Minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"FxPXjS0YcyKrooiG","formula":"10","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"FxPXjS0YcyKrooiG":"10"}},"counteraction":false,"ritual":null,"description":"A light, soothing breeze flows through the area, making it easier to rest and recover. Medicine checks attempted to benefit living creatures in the area get a +2 status bonus. Any living creature in the area also gets a +2 status bonus to saving throws against afflictions and, if it remains within the area for the full duration, regains 10 Hit Points. In addition, the cool breeze reduces the temperature effects of heat by one step for any creature in the area.\n\nHeightened (+2) The healing increases by 10 Hit Points.","source":{"provider":"PAIZO","sourceId":"C0D2eqzTAhiKm4j9","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ghostly-carrier","name":"Ghostly Carrier","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a Tiny, semi-corporeal figure with a form you choose. It hovers near you for the duration. When you Cast a Spell that has a range of touch, you can have the carrier move within range, deliver the spell to a creature there, and return to you. If the carrier must attempt a spell attack roll, it uses your normal bonuses. The carrier has your AC and saves, but it is destroyed by any damage.","source":{"provider":"PAIZO","sourceId":"rthC6dGm3nNrt1xN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghoulish-cravings","name":"Ghoulish Cravings","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","curse","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You touch the target to afflict it with the overwhelming desire to eat raw meat. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target is Sickened 1 by its unbidden hunger.\n\nFailure The target is Sickened 2 and can't reduce this condition below sickened 1 until it first consumes some raw meat; if the creature doesn't have access to raw meat, it can take a bite out of a corpse within reach as an Interact action.\n\nCritical Failure As failure, but the target can't reduce the condition below sickened 2 until it consumes raw meat.","source":{"provider":"PAIZO","sourceId":"JhRuR7Jj3ViShpq7","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gnaw-at-the-moon","name":"Gnaw at the Moon","kind":"RITUAL","rank":2,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"mooncakes and rare tea worth 100 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"yourself and the secondary casters","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Diplomacy (expert)","secondaryChecks":"Crafting, Occultism, or Religion","secondaryCasters":3},"description":"It's said that after his demise at the hands of jealous Fumeiyoshi, Tsukiyo's corpse was left unguarded; this provided a humble matron-rat opportunities to nibble at god flesh, a meal that transformed her into Lao Shu Po. Gnaw at the moon, an obscure folk magic ritual popular among Shenmen's downtrodden, allows you to honor the Old Rat Woman's audacity and unlikely ascent.\n\nThis ritual can only be performed on a night when the moon is visible in the sky above; you can't perform this ritual during a totally moonless night, while indoors, or while underground. Performing this ritual on the night of the full moon reduces the DCs of the ritual's skill checks by 2. You set out offerings of mooncakes and cups of tea on a flat surface (such as a table or a tray on the floor), assiduously ignore this food and drink, and praise the night's beauty while admiring and thanking the moon.\n\nAt the end of a successful ritual, bite marks appear on the mooncakes, and some of the tea disappears as if sipped while no one was looking. Supposedly, the ritual and offerings gain Lao Shu Po's attention, who sends her rodent children to eat and drink their fill and grant stolen blessings of moonlit sight. The effusive admiration for the moon is said to avert Tsukiyo's displeasure for commemorating the event of his murder; after all, old tales warn against giving offense to the moon, lest it slice your ears in retribution.\nCritical Success The targets gain darkvision.\n\nSuccess The targets gain low-light vision.\n\nFailure The ritual has no effect.\n\nCritical Failure You and the targets are Drained 1 for 24 hours. Your ears feel lacerated and raw as your earlobes become crisscrossed with tiny cuts.","source":{"provider":"PAIZO","sourceId":"yrsgOdj5oqp7lEQY","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.grave-impressions","name":"Grave Impressions","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 corpse","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You project a fragment of your senses into the corpse. While within 500 feet of the corpse (even if it's outside your line of sight or line of effect), you can see from where the target corpse had eyes using your normal visual senses, and you can hear from where the corpse had ears using your normal auditory senses. You can switch between your own vision and hearing, and the corpse's senses, with a single action that has the concentrate trait. If the corpse naturally lacked eyes or hearing organs in life, you cannot use that sense when using this spell. If the corpse is moved from its location, the spell ends.\n\nHeightened (4th) The duration increases to 1 hour.\n\nHeightened (6th) The duration lasts until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"Xrz6wPXDBUr27izR","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.guiding-star","name":"Guiding Star","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","detection","manipulate","mental"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature you've met","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call on the constellations of the night sky to guide a creature to the location where you Cast the Spell. Each time the target views the stars, it receives a mental nudge toward your chosen location, though it isn't compelled to follow. The target can recognize you as the source. If the creature goes to another planet or plane, the spell's effects are suppressed, but they resume if the creature returns.","source":{"provider":"PAIZO","sourceId":"L10q1ng6U3sega9S","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.harmonize-self","name":"Harmonize Self","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","monk","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"8","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"8"}},"counteraction":true,"ritual":null,"description":"You heal yourself in one of the following ways, chosen by you when you cast the spell.\n\n- You regain 8 Hit Points.\n\n- You attempt to cure one poison or disease afflicting you; attempt to counteract the affliction.\n\nHeightened (+1) If you choose to regain Hit Points, the Hit Points regained increase by 8.","source":{"provider":"PAIZO","sourceId":"qJZZdYBdNaWRJFER","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.heartbond","name":"Heartbond","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"sacramental beverages and a set of matching rings or other tokens worth 20 gp per secondary caster"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature or Religion (expert)","secondaryChecks":"Diplomacy, Society","secondaryCasters":2},"description":"You officiate the creation of a magical bond between two or more willing creatures, who are secondary casters of the ritual and must share genuine affection for one another. As part of the ritual, all members of the bond receive a ring, amulet, or similar token to symbolize their shared connection. They lose the effects of the ritual when not wearing the token, and the bond is broken if either token is destroyed.\n\nCreatures benefiting from a successful heartbond ritual can later participate in a heightened version of the ritual without requiring new checks by spending the required time and paying the difference of the two costs. A creature can be under the effects of multiple heartbond rituals at once.\nCritical Success Once per day, each bonded creature can use a 2-action activity, which has the concentrate trait, to learn the present state of one other bonded creature. The creature knows the other creature's direction and distance and any conditions affecting them. Each participant can cast message as a divine innate spell at will, but can target only another participant.\n\nSuccess As a critical success, except the bonded creatures can't cast message as a divine innate spell.\n\nFailure The ritual has no effect.\n\nCritical Failure Magical backlash creates discordant energy among the participants. For 1 week, each secondary caster is Clumsy 2 and Stupefied 2 whenever they are within 30 feet of another secondary caster.\nHeightened (6th) The cost increases to 300 gp per secondary caster. On a success, secondary casters permanently gain the effects of a 6th-rank telepathy spell, but only with each other","source":{"provider":"PAIZO","sourceId":"dZV8nZUKRhGIr6g9","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heat-metal","name":"Heat Metal","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 metal item or metal creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"ga830svjq2s25ahf","formula":"2d4","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6","ga830svjq2s25ahf":"1d4"}},"counteraction":false,"ritual":null,"description":"This spell heats the targeted metal to become red-hot for a moment. This is usually harmless to an unattended metal item, which doesn't get a saving throw, though the GM might rule that flammable materials connected to the object catch fire or melt. If you target an item worn or carried by a creature, or you target a creature made primarily of metal, the heat deals 4d6[fire] damage and 2d4[persistent,fire] damage to the creature, which must attempt a Reflex saving throw.\n\nIf you target an item held by the creature, the creature can the item to improve their degree of success by one step from the result of their saving throw. The persistent damage is associated with the object and damages whichever creature is holding or wearing it. It has no effect if no one is holding the item, but you continue to attempt flat checks to end the persistent damage as normal, since the item remains hot and can sear someone who picks it up.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and the object deals no persistent fire damage.\n\nFailure The creature takes full damage and the object deals full persistent damage.\n\nCritical Failure As failure, but the creature takes double damage and the object deals double persistent damage.\n\nHeightened (+1) The initial damage increases by 2d6 and the persistent damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"v4KzRPol5XQOOmk0","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.helpful-reload","name":"Helpful Reload","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger One of your allies makes a ranged Strike with a weapon with a reload of 1 or less\n\nRequirements Your ally has more ammunition for their ranged weapon available.\nWith a quick gesture, you reload your ally's weapon, allowing them to focus on fighting the enemy. You reload their weapon with a piece of mundane ammunition from the triggering creature's inventory.\nHeightened (4th) You reload your ally's weapon and grant them a +1 status bonus to their next Strike with this weapon.\n\nHeightened (6th) You reload your ally's weapon with the ammunition of their choice from their inventory. Your ally gains a +1 status bonus to their next Strike with this weapon.\n\nHeightened (8th) The spell no longer requires your ally to have appropriate ammunition available. You summon a single piece of common magical ammunition of 10th level or lower to reload your ally's weapon with. Your ally gains a +1 status bonus to their next Strike with this weapon.","source":{"provider":"PAIZO","sourceId":"0OFFXFdnMmFVlt8W","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.helpful-wood-spirits","name":"Helpful Wood Spirits","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Upon casting this spell, a cluster of little wood spirits tumbles into the area. They perform a simple task each round. These spirits are a magical echo of the true spirits that live on the Plane of Wood and can't be attacked, damaged, or otherwise interfered with. These spirits often look like kodama but can appear in any of the countless varieties of wood spirits that inhabit the Plane of Wood.\n\nChoose the kind of aid your wood spirits supply from the list below when you Cast the Spell. The first time each round you Sustain the spell, you can move the area occupied by the apparitions up to 10 feet and you can choose the kind of aid they provide this round.\n\n- Chores The wood spirits perform a minor manual task of your choice, such as cleaning, opening a door, picking up an unattended object, or carrying an object from one location to another. The spirits can't pick up or carry an object of greater than 2 Bulk.\n\n- Distract The wood spirits distract your foes, clambering all over their feet and bodies and being a nuisance. Creatures in the area are unless they succeed at a Reflex save.\n\n- Obstacle The wood spirits fill the area as a chaotic, bouncing mass. The area they occupy is difficult terrain.\n\n- Search The wood spirits in the area they occupy, using your Perception check as their own. You learn anything they do from Seeking in this way.","source":{"provider":"PAIZO","sourceId":"kcYCWMd1NVCJ5Zbu","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hidebound","name":"Hidebound","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"},"requirements":"A creature within range is hit with a Strike that deals physical damage."},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range is hit with a Strike that deals physical damage.\n\nThe target's skin erupts in thick hide or dense scales. It gains resistance 5 to physical damage, except adamantine, until the beginning of its next turn.\n\nHeightened (+2) The resistance increases by 3.","source":{"provider":"PAIZO","sourceId":"3TuGuGZqyOBmWp7N","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.horrifying-blood-loss","name":"Horrifying Blood Loss","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","curse","emotion","fear","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature taking bleed damage","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You curse the target, filling it with terror at the loss of its blood. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Frightened 1.\n\nFailure The target is Frightened 2. Until it stops bleeding, its frightened value can't decrease below frightened 1.\n\nCritical Failure As failure, but the target is Frightened 3.\n\nHeightened (4th) You even terrify witnesses with the copious quantities of blood. You can target up to four creatures as secondary targets. These secondary targets don't need to be bleeding but must be able to see the primary target. Secondary targets must also attempt Will saves, with the same results, except their restriction on decreasing their frightened value depends on whether the primary target is still bleeding.","source":{"provider":"PAIZO","sourceId":"LrRyNA2bo5UwBxud","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.humanoid-form","name":"Humanoid Form","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform your appearance to that of a Small or Medium humanoid, such as a dwarf, elf, goblin, halfling, human, or orc. You gain the humanoid trait in addition to your other traits while in this form, as well as any trait related to the creature's kind (such as goblin or human). If this transformation reduces your size, it reduces your reach accordingly (typically to 5 feet). This transformation doesn't change your statistics in any way, and you don't gain any special abilities of the humanoid form you assume. You can still wear and use your gear, which changes size (if necessary) to match your new form. If items leave your person, they return to their usual size.\n\nHumanoid form grants you a +4 status bonus to Deception checks to pass as a generic member of the chosen ancestry, and you add your level even if you're untrained, but you can't make yourself look like a specific person. If you want to Impersonate an individual, you still need to create a disguise, though the GM won't factor in the difference in ancestry when determining the DC of your Deception check. You can Dismiss this spell.\n\nHeightened (3rd) You gain darkvision or low-light vision if the form you assume has that ability.\n\nHeightened (5th) You can take on the appearance of a Large humanoid. If this increases your size, you gain the effects of the enlarge spell.","source":{"provider":"PAIZO","sourceId":"2qGqa33E4GPUCbMV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hunters-luck","name":"Hunter's Luck","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","fortune","ranger"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You attempt a check to about a creature, but you haven't rolled yet.\n\nYou have a preternatural ability to remember details about your foes. Roll the triggering check twice and use the better result.","source":{"provider":"PAIZO","sourceId":"GfrKNJ9pNeATiKCc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ignite-fireworks","name":"Ignite Fireworks","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate","sonic"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"1d8","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8","1":"1d8","2":"","3":""}},"counteraction":false,"ritual":null,"description":"A brilliant and clamorous display of sparks and colorful fireworks explode around your enemies, dealing 1d8 fire damage and 1d8 sonic damage to creatures within a 10-foot burst. All creatures in the area must attempt a Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is for 1 round.\n\nFailure The creature takes full damage and is dazzled for 3 rounds.\n\nCritical Failure The creature takes double damage, takes 1d4[persistent,fire] damage, and is dazzled for 1 minute.\n\nHeightened (+2) The initial fire damage increases by 1d8, the sonic damage increases by 1d8, and the persistent fire damage a creature takes on a critical failure increases by 1d4.","source":{"provider":"PAIZO","sourceId":"3GXU3ugrwLv0P7AH","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.illusory-creature","name":"Illusory Creature","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate","olfactory","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusory image of a Large or smaller creature. It generates the appropriate sounds, smells, and feels believable to the touch. If you and the image are ever farther than 500 feet apart, the spell ends.\n\nThe image can't speak, but you can use your actions to speak through the creature, with the spell disguising your voice as appropriate. You might need to attempt a Deception or Performance check to mimic the creature, as determined by the GM. This is especially likely if you're trying to imitate a specific person and engage with someone that person knows.\n\nIn combat, the illusion can use 2 actions per turn, which it uses when you Sustain the spell. It uses your spell attack modifier for attack rolls and your spell DC for its AC. Its saving throw modifiers are equal to your spell DC – 10. It is substantial enough that it can flank other creatures. If the image is hit by an attack or fails a save, the spell ends.\n\nThe illusion can cause damage by making the target believe the illusion's attacks are real, but it cannot otherwise directly affect the physical world. If the illusory creature hits with a Strike, the target takes 3d4[mental] damage. The illusion's Strikes are nonlethal. If the damage doesn't correspond to the image of the monster—for example, if an illusory Large dragon deals only 5 damage—the GM might allow the target to attempt an immediate Perception check to disbelieve the spell. Any relevant resistances and weaknesses apply if the target thinks they do, as judged by the GM. For example, if the illusion wields a warhammer and attacks a creature resistant to bludgeoning damage, the creature would take less mental damage. However, illusory damage does not deactivate regeneration or trigger other effects that require a certain damage type. The GM should track illusory damage dealt by the illusion.\n\nAny creature that touches the image or uses the action to examine it can attempt to disbelieve your illusion. When a creature disbelieves the illusion, it recovers from half the damage it had taken from it (if any) and doesn't take any further damage from it.\n\nHeightened (+1) The damage of the image's Strikes increases by 1d4, and the maximum size of creature you can create increases by one (to a maximum of Gargantuan).","source":{"provider":"PAIZO","sourceId":"f8SBoXiXQjlCKqly","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.illusory-shroud","name":"Illusory Shroud","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud the target in subtle illusions that make it difficult to detect. The target gains a +1 status bonus to Stealth checks to or . For the duration, the target can become to a creature even if they don't have cover and aren't otherwise from that creature. Even if the target isn't concealed or doesn't have cover or greater cover at the end of a Sneak action, the target isn't automatically observed.","source":{"provider":"PAIZO","sourceId":"kLyyJayja75K9rXX","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.imitate-fauna","name":"Imitate Fauna","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","illusion","manipulate","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing animal","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You use your knowledge of nature to pass the target off as a common animal of the same size, representing a species chosen when the spell is cast. This covers the target's visual appearance, scent, and voice. The target can communicate with other members of the species as though they shared a language but can't speak other languages while the spell persists.\n\nCasting imitate fauna counts as setting up a disguise for the purpose of the action. It allows the target to ignore any circumstance penalties they might take for being disguised as dissimilar creatures, and it gives the target a +4 status bonus to Deception checks to prevent other animals from seeing through their disguise. You can Dismiss this spell.\n\nHeightened (5th) You can target up to six willing animals.","source":{"provider":"PAIZO","sourceId":"HkjeegDsA5Wq0hR2","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.imp-sting","name":"Imp Sting","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","evil","manipulate","poison"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reproduce an imp's evil, poisonous sting, stabbing at an enemy and possibly affecting them with the devil's benumbing venom. You deal 1d4[piercing] damage to the touched creature and afflict the creature with imp venom. If the target takes piercing damage, they also take 1d6[spirit] damage and must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 1d6[poison] damage.\n\nFailure The target is afflicted with Imp Venom at stage 1.\n\nCritical Failure The target is afflicted with imp venom at stage 2.\n\nImp Venom (poison) Level 3\n\nMaximum Duration 6 rounds\n\nStage 1 1d6[poison] damage and Clumsy 1\n\nStage 2 1d6[poison] damage, Clumsy 1, and Slowed 1 (1 round).","source":{"provider":"PAIZO","sourceId":"oryfsRK27jAUnziw","book":"Pathfinder #160: Assault on Hunting Lodge Seven","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.impart-empathy","name":"Impart Empathy","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 animal","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You expand the target's ability to understand social cues that are normally beyond its comprehension. Any creature to which the target isn't unfriendly or hostile can use Diplomacy to on it and to make very simple Requests of it. This doesn't render the animal any more inclined to help than it otherwise would be.\n\nHeightened (4th) The spell can also target plants and fungi.","source":{"provider":"PAIZO","sourceId":"VJW3IzDpAFio7uls","book":"Pathfinder #175: Broken Tusk Moon","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.impeccable-flow","name":"Impeccable Flow","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attune yourself to an underlying cosmic order to the world. While you remain in tune with this power, you gain a +1 status bonus to Perception checks, saving throws, and skill checks. If you critically fail any check while under the effects of this spell, the bonus ends and you instead have a -1 status penalty to all checks for the remaining duration.\n\nHeightened (5th) The status bonus increases to +2.\n\nHeightened (8th) The status bonus increases to +3.\nNote: The automation for the critical failure effect defaults to 10 rounds and must be altered manually.","source":{"provider":"PAIZO","sourceId":"8VzbumNyMEdSzZSz","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.inner-radiance-torrent","name":"Inner Radiance Torrent","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["force","light"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"2 to 2 rounds"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d4","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"You gradually manifest your spiritual energy into your cupped hands before firing off a storm of bolts and beams that deal 4d4 force damage to all creatures in a 60-foot line. Creatures in the area must attempt a basic Reflex save. On a critical failure, they're also blinded for 1 round. The number of actions you spend when Casting this Spell determines the area. If the line passes through an area of magical darkness or targets a creature affected by magical darkness, inner radiance torrent attempts to counteract the darkness.\n\n2 (somatic, verbal) The line is 60 feet long.\n\n3 (material, somatic, verbal) The line is {120 feet} long.\n\nTwo Rounds The line is 120 feet long. If you spend 3 actions casting the spell, you can avoid finishing the spell and spend another 3 actions on your next turn to empower the spell even further. If you choose to do so, the damage dealt by this spell increases by 4d4, and you enter a shining state for 1 minute, causing you to glow with light and deal 1[force] damage to creatures that end their turn adjacent to you.\nHeightened (+1) The initial damage, as well as the additional damage for the 2-round casting time, each increase by 2d4, and the damage to adjacent creatures dealt while in your shining state increases by 1.","source":{"provider":"PAIZO","sourceId":"eSEmqOBuywoJ6tYd","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.instant-armor","name":"Instant Armor","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","contingency","extradimensional","manipulate","metal"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Upon casting this spell, the armor you're wearing is whisked away into an extradimensional space that's linked to you. If the armor is magical and invested by you, it remains invested while in this space, though you don't gain its benefits. You then gain the action; once you use the action, the spell ends. If the action hasn't been used by the time the spell's duration ends, the extradimensional space collapses, ejecting the armor's pieces on the ground under you.","source":{"provider":"PAIZO","sourceId":"uiv8FKuxE8HOWTxW","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.inveigle","name":"Inveigle","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils worth a total value of 10 gp × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature of a level no greater than double the inveigle ritual's rank","area":null},"duration":{"text":"1 year or until dismissed","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert), Occultism (expert), or Religion (expert)","secondaryCasters":0},"description":"You win over the target's mind, causing it to see you as a close and trusted friend and look upon your every suggestion as reasonable. The target is helpful toward you, so it will go out of its way to help you. As with any other helpful creature, there are limits to what you can ask of it. If you ever ask the target to do something completely against its nature or needlessly harmful to the target or its interests, not only does it refuse, but it also can attempt a Will save to end the effect early. Because of the casting time and range, it's generally difficult to cast this ritual unless the target is willing (perhaps convinced the ritual will have some other effect) or restrained. If the creature is unwilling to accept the ritual, it can attempt a Will save to negate the effect.\nCritical Success The ritual succeeds and the target takes a -4 status penalty to Will saves to end the effect.\n\nSuccess The ritual succeeds.\n\nFailure The ritual fails.\n\nCritical Failure The ritual fails and the target instead hates you, becoming hostile to you for the duration.\nHeightened (6th) You can use inveigle on a creature up to 1 mile away throughout the casting, as long as you have a piece of the creature's body, which you mix into the oils used in the cost. The base cost is 100 gp. The duration is shorter, and based on how large a piece of the creature's body you use: 1 week for blood, hair, scales, and the like, or 1 month for a hand or similarly substantial body part.","source":{"provider":"PAIZO","sourceId":"5pwK2FZX6QwgtfqX","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invisibility","name":"Invisibility","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Illusions bend light around the target, rendering it . This makes it to all creatures, though the creatures can attempt to find the target, making it to them instead. If the target uses a hostile action, the spell ends after that hostile action is completed.\n\nHeightened (4th) The spell lasts 1 minute, but it doesn't end if the target uses a hostile action.","source":{"provider":"PAIZO","sourceId":"XXqE1eY3w3z6xJCB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invoke-the-crimson-oath","name":"Invoke the Crimson Oath","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Brandishing your weapon and shouting the final line of the Crimson Oath, you unleash a blast of destructive ruby energy. You must be wielding a melee weapon, and you perform this spell's somatic component by swinging the weapon in a downward arc. You deal normal melee damage for your weapon, including all appropriate bonuses, penalties, modifiers, and properties, to each creature in the spell's area; they must each attempt a basic Fortitude save. A creature that critically fails this save also suffers any additional effect you would normally inflict with your weapon on a critical hit; if the creature that critically fails its save is also immune to critical hits, it merely fails the save instead.\n\nYou can convert all the physical damage from this spell into vitality damage against all undead creatures in the area.","source":{"provider":"PAIZO","sourceId":"AsKLseOo8hwv5Jha","book":"Pathfinder Lost Omens Character Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.iron-gut","name":"Iron Gut","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your mouth, esophagus, and stomach become incredibly elastic and tougher than metal. For the duration of the spell, you can reach down your throat to store or retrieve a single object of light or negligible Bulk in your stomach, as though your stomach were a backpack or other container. Storing and retrieving an item in this way requires an Interact action. The object must be small enough to reasonably fit within your stomach. It is very difficult for other creatures to notice that you are hiding an object in this way; passive observers can't possibly notice and you gain a +4 circumstance bonus to your Stealth checks to unless the searcher specifically searches your mouth and stomach. If at the end of the spell's duration you still have an object stored in your stomach, it is violently expelled, dealing 1d6 damage to you.\n\nHeightened (3rd) The duration increases to 8 hours.","source":{"provider":"PAIZO","sourceId":"IhwREVWG0OzzrbWA","book":"Pathfinder Lost Omens Gods & Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.kgalaserkes-axes","name":"Kgalaserke's Axes","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 or 2"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The folklore and tales surrounding the legendary hero Kgalaserke are so widespread and well known that a hundred lifetimes would not be enough to have accomplished everything she is reputed to have done. Nevertheless, the stories all contain a unifying theme of her martial prowess despite the odds being stacked against her.\n\n1 You briefly describe Kgalaserke's signature axes and how she came to receive them. The target gains a +1 status bonus to attack rolls for the spell's duration.\n\n2 You revel in a tale of Kgalaserke striking down a foe after a struggle. For the spell's duration, when the target is damaged by a creature's attack, the target gains a +2 circumstance bonus to damage against that creature for 1 round.","source":{"provider":"PAIZO","sourceId":"yo1eB5Xz21AYfWCI","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.knock","name":"Knock","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 door, lock, or container","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make the target easier to open. Knock grants a +4 status bonus to any creature that tries to open the target door, lock, or container with an Athletics or a Thievery check. You can attempt a Thievery check to open the target as part of casting knock, and you add your level even if you're untrained.\n\nKnock counteracts .","source":{"provider":"PAIZO","sourceId":"6Ot4N22t5tPD51BO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.last-nights-vigil","name":"Last Night's Vigil","kind":"RITUAL","rank":2,"rarity":"RARE","traits":["healing"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"},"cost":"rare sticks of incense worth 10 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature whom you love","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (trained) or Survival (expert)","secondaryCasters":0},"description":"Obscure folktales state on the first day of spring, the Mother of Secrets wanders Tian Xia to dispense blessings of health upon the elderly. Last night's vigil is a folk ritual inspired by these stories.\n\nThis simple ritual can only be performed at night, in the presence of someone whom you love and who's ill, hurt, or otherwise unwell. You must stay awake through the night, keeping the sticks of incense lit to guide the goddess's passage. If you're indoors, you should keep a door or window slightly ajar to receive her holy presence. If performed on a winter night, the DCs of the ritual's skill checks are reduced by 1; if performed on the last night of winter before spring, the DCs are instead reduced by 2.\n\nIf the ritual is successful, you fall asleep for the briefest of moments to the sound of snowfall and the swishing of a horse tail whisk. When you awaken moments later, your loved one smiles at you, hopefully in better health.\nCritical Success The target's Hit Points are fully restored, and all diseases that are equal or lower level than twice the ritual's spell rank that they're currently suffering from reduce their stage by 1. If this reduces a disease's stage below 1, it cures that affliction.\n\nSuccess The target's Hit Points are fully restored, and one disease of a level that's equal to or lower than twice the ritual's spell rank that they're currently suffering from reduces its stage by 1. If this reduces the disease's stage below 1, it cures that affliction.\n\nFailure The ritual has no effect.\n\nCritical Failure You're for the next 24 hours.\nHeightened (4th) You can choose when you perform the ritual whether it affects curses or diseases.\n\nHeightened (6th) You can affect curses and diseases simultaneously.","source":{"provider":"PAIZO","sourceId":"INEAWirvb8c1eAFD","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.laughing-fit","name":"Laughing Fit","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target is overtaken with uncontrollable laughter. It must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is plagued with uncontrollable laughter. It can't use reactions.\n\nFailure The target is Slowed 1 and can't use reactions.\n\nCritical Failure The target falls and can't use actions or reactions for 1 round. It then takes the effects of a failure.","source":{"provider":"PAIZO","sourceId":"tlSE7Ly8vi1Dgddv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lifelink-surge","name":"Lifelink Surge","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["focus","healing","manipulate","summoner","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"4 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make a quick gesture, tracing the link between yourself and your eidolon and drawing on your connection to slowly strengthen your shared life force. Your eidolon gains Fast Healing 4 for 4 rounds.\n\nHeightened (+1) The fast healing increases by 2.","source":{"provider":"PAIZO","sourceId":"lOZhcvtej10TqlQm","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.light-of-revelation","name":"Light of Revelation","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","light","manipulate","revelation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30-foot emanation"},"area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shed a luminous aura, illuminating a 30-foot radius with bright light. You and all allies in this area gain a +1 status bonus to Perception checks to detect or creatures, as well as Hidden objects, doors, and other features.","source":{"provider":"PAIZO","sourceId":"ou56ShiFH7GWF8hX","book":"Pathfinder Lost Omens Character Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lock-item","name":"Lock Item","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 object held by 1 creature and the creature holding it","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"One object held by a creature becomes fused to that creature's hand and can't be put down. To or the item, the result of the skill check must exceed the spell's DC or the normal DC, whichever is higher. To voluntarily drop the weapon, the target must spend an Interact action rather than a free action, and then succeed at a Reflex save; the target must also attempt a Reflex save to Interact to put away or swap the object. On a failed save, the action is wasted, but on a success, they drop the item and the spell ends. An unwilling creature must attempt an initial Reflex save against lock item. A willing creature can choose to critically fail the saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature is affected for 1 round.\n\nFailure The creature is affected for 4 rounds.\n\nCritical Failure The creature is affected for 1 minute.\nHeightened (+2) You can target either one additional object held by the same creature or one additional object held by one additional creature.","source":{"provider":"PAIZO","sourceId":"qFO9HgplrShoaAPY","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.loose-times-arrow","name":"Loose Time's Arrow","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 6 creatures","area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pluck the time stream like a bow—pull one string back, release, and watch a creature fly. All affected targets are . They can use the extra action only to Step or Stride.","source":{"provider":"PAIZO","sourceId":"mLAYvbafVKfBgEhz","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lucky-month","name":"Lucky Month","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["attack"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a favorite food or drink and a wearable token with personal or familial significance worth 10 gp total"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature and 1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (trained)","secondaryChecks":"Crafting, Performance, Society","secondaryCasters":3},"description":"You imbue the provided token with luck. You choose a single creature within range during the ritual's performance to become the recipient of the token's luck. That creature has access to the token's luck as long as they're wearing the token. If the token is stolen or lost, they lose access to its luck until the token is recovered. The token loses its luck if it's destroyed or after the duration noted in the ritual's effects has elapsed.\n\nCritical Success You can call upon the token's luck. Once per week, when rolling a saving throw or skill check, you can use the token's power and roll twice, taking the higher result. This is a fortune effect. The token keeps its luck for 1 month.\n\nSuccess As a critical success, except you can only call upon the token's power once during the lucky month.\n\nFailure The ritual has no effect.\n\nCritical Failure Magical backlash creates ill luck. Once per week, the ritual's recipient must roll twice and take the worse result for their first significant saving throw or skill check of the week, as determined by the GM. This is a misfortune effect. This ill luck remains for 1 month and applies to the recipient whether or not they're wearing the token.","source":{"provider":"PAIZO","sourceId":"MkHshwYy2UOeEHRR","book":"Pathfinder Lost Omens Travel Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lucky-number","name":"Lucky Number","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","contingency","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When you Cast this Spell, roll 1d20 and make a note of the result. You gain the reaction; once you use the reaction, the spell ends, and you become temporarily immune to lucky number until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"rDDYGY2ekZ1yVv7q","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.luminous-stardust-healing","name":"Luminous Stardust Healing","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","focus","healing","manipulate","spirit"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"Is7bQgOuT0P4zHZJ","formula":"16","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Is7bQgOuT0P4zHZJ":"8"}},"counteraction":true,"ritual":null,"description":"You scatter twinkling sparks from your sentinel weapon, replenishing your allies' fighting spirit and driving out evil. The target regains 16 Hit Points. If they were affected by a possession effect, you attempt to counteract the effect, casting out the possessing entity on a success and preventing them from possessing the target again for 1 week. If you fail, the entity is immune to being cast out by this spell for 1 week, though you can still heal the target as normal.\nHeightened (+1) The amount of healing increases by 8.","source":{"provider":"PAIZO","sourceId":"1H3T9UwxW44Y0YaS","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.magic-warrior-aspect","name":"Magic Warrior Aspect","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the aspect of the animal from your mask, gaining physical features reminiscent of that animal. You morph slightly into that creature, gaining the Speeds and senses you would gain from using to turn into the type of animal your mask represents; these special Speeds can't be increased by status bonuses or item bonuses.","source":{"provider":"PAIZO","sourceId":"b6UnLNikoq2Std1f","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magic-warrior-transformation","name":"Magic Warrior Transformation","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform into the animal from your mask. You gain the effects of , heightened to magic warrior transformation's level, and you can transform into only the type of animal your mask represents.","source":{"provider":"PAIZO","sourceId":"tp4K7mYDL5MRHvJc","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magnetic-attraction","name":"Magnetic Attraction","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 10 metal objects with a total Bulk of 1 or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You adjust your magnetic polarity, plucking daggers from hands and coins from belts. The targeted objects fly to your location, letting you catch them easily in your hands, or dropping to the ground at your position, at your discretion. Unattended objects fly to you automatically. If you target secured objects or those in another creature's possession (such as sheathed weapons), you must attempt to Disarm the creature of the metal objects, making a spell attack roll instead of an Athletics check to do so.\n\nInstead of drawing the objects to yourself, you can polarize a single metal object within range, designating it as a lodestone and causing the metal objects to fly to it instead. The lodestone must be at least three times the total Bulk of the targeted metal objects. Objects will stick to the lodestone for 1 minute, though they can be wrenched away with an Interact action.","source":{"provider":"PAIZO","sourceId":"7dKtMehJ6YrXwJLR","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magnetic-repulsion","name":"Magnetic Repulsion","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You adjust your magnetic polarity, causing metal objects to jump and shudder away from you. Attacks made with metal objects against you take a -1 status penalty, and the squares adjacent to you are difficult terrain for creatures wearing metal armor. For creatures made entirely of metal, the penalty to their attack rolls is -2 and the squares adjacent to you are greater difficult terrain.\n\nWhile this spell is active, you require an additional Interact action before using a metal object (including to Strike with a metal weapon), and if you're wearing metal armor, you're Slowed 1.\n\nHeightened (+3) The status penalty to attack rolls increases by 1.","source":{"provider":"PAIZO","sourceId":"24U1b9K4Lj94cgaj","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.manifestation-of-spirits","name":"Manifestation of Spirits","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You open the target's eyes to the plethora of spirits surrounding it—and it sees all these spirits as menacing and powerful. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target believes every spirit it sees is an imminent threat. It's Stupefied 3 for 1 round.\n\nFailure As success, but the effect lasts 1 minute.\n\nCritical Failure As failure, and the target becomes for 1 round.\nHeightened (6th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"O1ZLfeOJpHbG9G6B","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mark-of-blood","name":"Mark of Blood","kind":"SPELL","rank":2,"rarity":"RARE","traits":["curse","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 piercing or slashing weapon you're wielding","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You place a drop of your blood on a weapon and charge it with magic so that you transfer a small amount of your life essence with your attack. The next creature you successfully Strike with the weapon during the spell's duration takes damage as normal from the attack and must then attempt a Will save; regardless of the outcome of this saving throw, the duration of mark of blood ends. You can have up to one creature cursed by mark of blood at any one time. If you use this spell to mark a different creature, the curse afflicting the previous creature ends.\nCritical Success The creature is unaffected.\n\nSuccess The creature gains a softly glowing mark that resembles Achaekek's symbol somewhere on their body (such as the forehead or back of the hand). This mark can be by clothing, but is otherwise permanent until the curse is removed.\n\nFailure As success, but you can to attempt to know the direction and general distance (within a mile) to the marked creature if the creature is alive and both you and the creature are on the same plane of existence. When you Seek in this way, you attempt a Perception check against the marked creature's Will DC. On a success, you gain the information, which is accurate at the moment that you Seek. On a critical failure, the curse ends, and the creature's mark vanishes.\n\nCritical Failure As failure, but your Perception checks to Seek the marked creature are automatically successful.","source":{"provider":"PAIZO","sourceId":"Oy6qBhzayCnqOiEO","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
